mapper.select:
select a.* from ( select t2.area, NVL(round(t1.sublease / 10000, 2), 0) sublease, NVL(round(t1.lease / 10000, 2), 0) lease, NVL(round(t1.lease_back / 10000, 2), 0) lease_back, NVL(round(t1.GENERAL_OPERATING_LEASE / 10000, 2), 0) GENERAL_OPERATING_LEASE, NVL(round(t1.GENERIC_DEVICE / 10000, 2), 0) GENERIC_DEVICE, NVL(round(t1.SPECIALIZED_DEVICE / 10000, 2), 0) SPECIALIZED_DEVICE, NVL(round(t1.TRANSPORTATION_DEVICE / 10000, 2), 0) TRANSPORTATION_DEVICE, NVL(round(t1.ELECTRONICS_DEVICE / 10000, 2), 0) ELECTRONICS_DEVICE, NVL(round(t1.ELECTRICAL_DEVICE / 10000, 2), 0) ELECTRICAL_DEVICE, NVL(round(t1.LAND_HOUSES_STRUCTURES / 10000, 2), 0) LAND_HOUSES_STRUCTURES, NVL(round(t1.OTHER_LEASEHOLD / 10000, 2), 0) OTHER_LEASEHOLD from (select t.area city, sum(lease + lease_back) sublease, sum(lease) lease, sum(lease_back) lease_back, sum(GENERAL_OPERATING_LEASE) GENERAL_OPERATING_LEASE, sum(GENERIC_DEVICE) GENERIC_DEVICE, sum(SPECIALIZED_DEVICE) SPECIALIZED_DEVICE, sum(TRANSPORTATION_DEVICE) TRANSPORTATION_DEVICE, sum(ELECTRONICS_DEVICE) ELECTRONICS_DEVICE, sum(ELECTRICAL_DEVICE) ELECTRICAL_DEVICE, sum(LAND_HOUSES_STRUCTURES) LAND_HOUSES_STRUCTURES, sum(OTHER_LEASEHOLD) OTHER_LEASEHOLD from (select NVL((select case p.description when '内蒙古自治区' then '内蒙古' when '黑龙江省' then '黑龙江' when '广西壮族自治区' then '广西' when '西藏自治区' then '西藏' when '宁夏回族自治区' then '宁夏' when '新疆维吾尔自治区' then '新疆' else substr(p.description,1,2) end name from fnd_city f, fnd_province p where f.city = p.city and f.province = p.province), '境外') area, NVL(sum((select sum((select sum(ccc.principal - ccc.received_principal) from con_contract_cashflow ccc where cc.contract_id = ccc.contract_id and cc.contract_status = 'INCEPT' and cc.data_class = 'NORMAL')) from con_contract cc where cc.project_id = p.project_id and p.business_type = 'LEASE')), 0) lease, NVL(sum((select sum((select sum(ccc.principal - ccc.received_principal) from con_contract_cashflow ccc where cc.contract_id = ccc.contract_id and cc.contract_status = 'INCEPT' and cc.data_class = 'NORMAL')) from con_contract cc where cc.project_id = p.project_id and p.business_type = 'LEASEBACK')), 0) lease_back, NVL(sum((select sum((select sum(ccc.principal - ccc.received_principal) from con_contract_cashflow ccc where cc.contract_id = ccc.contract_id and cc.contract_status = 'INCEPT' and cc.data_class = 'NORMAL')) from con_contract cc where cc.project_id = p.project_id and p.business_type = 'GENERAL_OPERATING_LEASE')), 0) GENERAL_OPERATING_LEASE, NVL(sum((select sum((select sum(ccc.principal - ccc.received_principal) from con_contract_cashflow ccc where cc.contract_id = ccc.contract_id and cc.contract_status = 'INCEPT' and cc.data_class = 'NORMAL')) from con_contract cc where cc.project_id = p.project_id and p.project_id in (select pp.project_id from prj_project_lease_item pp, hls_lease_item hlt where hlt.asset_types = 'GENERIC_DEVICE' and hlt.lease_item_id = pp.lease_item_id and pp.project_id = p.project_id))), 0) GENERIC_DEVICE, NVL(sum((select sum((select sum(ccc.principal - ccc.received_principal) from con_contract_cashflow ccc where cc.contract_id = ccc.contract_id and cc.contract_status = 'INCEPT' and cc.data_class = 'NORMAL')) from con_contract cc where cc.project_id = p.project_id and p.project_id in (select pp.project_id from prj_project_lease_item pp, hls_lease_item hlt where hlt.asset_types = 'SPECIALIZED_DEVICE' and hlt.lease_item_id = pp.lease_item_id and pp.project_id = p.project_id))), 0) SPECIALIZED_DEVICE, NVL(sum((select sum((select sum(ccc.principal - ccc.received_principal) from con_contract_cashflow ccc where cc.contract_id = ccc.contract_id and cc.contract_status = 'INCEPT' and cc.data_class = 'NORMAL')) from con_contract cc where cc.project_id = p.project_id and p.project_id in (select pp.project_id from prj_project_lease_item pp, hls_lease_item hlt where hlt.asset_types = 'TRANSPORTATION_DEVICE' and hlt.lease_item_id = pp.lease_item_id and pp.project_id = p.project_id))), 0) TRANSPORTATION_DEVICE, NVL(sum((select sum((select sum(ccc.principal - ccc.received_principal) from con_contract_cashflow ccc where cc.contract_id = ccc.contract_id and cc.contract_status = 'INCEPT' and cc.data_class = 'NORMAL')) from con_contract cc where cc.project_id = p.project_id and p.project_id in (select pp.project_id from prj_project_lease_item pp, hls_lease_item hlt where hlt.asset_types = 'ELECTRONICS_COMMUNICATIONS_DEVICE' and hlt.lease_item_id = pp.lease_item_id and pp.project_id = p.project_id))), 0) ELECTRONICS_DEVICE, NVL(sum((select sum((select sum(ccc.principal - ccc.received_principal) from con_contract_cashflow ccc where cc.contract_id = ccc.contract_id and cc.contract_status = 'INCEPT' and cc.data_class = 'NORMAL')) from con_contract cc where cc.project_id = p.project_id and p.project_id in (select pp.project_id from prj_project_lease_item pp, hls_lease_item hlt where hlt.asset_types = 'ELECTRICAL_DEVICE' and hlt.lease_item_id = pp.lease_item_id and pp.project_id = p.project_id))), 0) ELECTRICAL_DEVICE, NVL(sum((select sum((select sum(ccc.principal - ccc.received_principal) from con_contract_cashflow ccc where cc.contract_id = ccc.contract_id and cc.contract_status = 'INCEPT' and cc.data_class = 'NORMAL')) from con_contract cc where cc.project_id = p.project_id and p.project_id in (select pp.project_id from prj_project_lease_item pp, hls_lease_item hlt where hlt.asset_types = 'LAND_HOUSES_STRUCTURES' and hlt.lease_item_id = pp.lease_item_id and pp.project_id = p.project_id))), 0) LAND_HOUSES_STRUCTURES, NVL(sum((select sum((select sum(ccc.principal - ccc.received_principal) from con_contract_cashflow ccc where cc.contract_id = ccc.contract_id and cc.contract_status = 'INCEPT' and cc.data_class = 'NORMAL')) from con_contract cc where cc.project_id = p.project_id and p.project_id in (select pp.project_id from prj_project_lease_item pp, hls_lease_item hlt where hlt.asset_types = 'OTHER_LEASEHOLD' and hlt.lease_item_id = pp.lease_item_id and pp.project_id = p.project_id))), 0) OTHER_LEASEHOLD, cc.LEASE_START_DATE from prj_project p left join con_contract cc on cc.project_id = p.project_id
where to_char(cc.LEASE_START_DATE,'yyyy-mm') <= #{periodNameN}
group by p.city, cc.LEASE_START_DATE) t
group by t.area) t1, (select a.value_name area from ((select p.province value_code, case p.description when '内蒙古自治区' then '内蒙古' when '黑龙江省' then '黑龙江' when '广西壮族自治区' then '广西' when '西藏自治区' then '西藏' when '宁夏回族自治区' then '宁夏' when '新疆维吾尔自治区' then '新疆' else substr(p.description,1,2) end value_name from fnd_province p where p.description not in ('台湾省', '澳门特别行政区', '香港特别行政区')) union all (select 100000 as value_code, '境外' value_name from dual)) a) t2 where t2.area = t1.city(+) ) a
1=1
and a.area = #{areaN}

select t.* from ( select t.* from (select economic_component, total, LARGE_SCALE, MEDIUM, SMALL_SIZED, SMALL_only, MINIATURE, MINIATURE_only from (select economic_component, sum(LARGE_SCALE + MEDIUM + SMALL_SIZED + SMALL_only + MINIATURE + MINIATURE_only) total, LARGE_SCALE, MEDIUM, SMALL_SIZED, SMALL_only, MINIATURE, MINIATURE_only from (select substr(t2.value_name, 3) economic_component, NVL(round(sum(t1.LARGE_SCALE) / 10000, 2), 0) LARGE_SCALE, NVL(round(sum(t1.MEDIUM) / 10000, 2), 0) MEDIUM, NVL(round(sum(t1.SMALL_SIZED) / 10000, 2), 0) SMALL_SIZED, NVL(round(sum(t1.SMALL_only) / 10000, 2), 0) SMALL_only, NVL(round(sum(t1.MINIATURE) / 10000, 2), 0) MINIATURE, NVL(round(sum(t1.MINIATURE_only) / 10000, 2), 0) MINIATURE_only from (select economic_indu_classify, (case when t.enterprise_scale = 'LARGE_SCALE' then t.total_rental end) LARGE_SCALE, (case when t.enterprise_scale = 'MEDIUM' then t.total_rental end) MEDIUM, (case when t.enterprise_scale = 'SMALL_SIZED' and t.finance_amount > 10000000 then t.total_rental end) SMALL_SIZED, (case when t.enterprise_scale = 'SMALL_SIZED' and t.finance_amount < 10000000 then t.total_rental end) SMALL_only, (case when t.enterprise_scale = 'MINIATURE' and t.finance_amount > 10000000 then t.total_rental end) MINIATURE, (case when t.enterprise_scale = 'MINIATURE' and t.finance_amount < 10000000 then t.total_rental end) MINIATURE_only from (select cc.contract_id, cc.finance_amount, sum(ccc.principal - ccc.received_principal) total_rental, hbm.enterprise_scale, cc.contract_name, (SELECT t.description FROM hls_stat_class t WHERE t.class_usage = 'BIZ_PARTNER' AND t.enabled_flag = 'Y' and t.CLASS_ID = (SELECT t.parent_class_id FROM hls_stat_class t WHERE t.class_usage = 'BIZ_PARTNER' AND t.enabled_flag = 'Y' and t.CLASS_ID = hbm.economic_indu_classify)) economic_indu_classify, pq.lease_start_date from con_contract_cashflow ccc, con_contract cc left join prj_quotation pq on cc.quotation_id = pq.quotation_id, hls_bp_master hbm where cc.contract_id = ccc.contract_Id and cc.contract_status = 'INCEPT' and cc.data_class = 'NORMAL' and cc.tenant_id = hbm.bp_id and hbm.bp_class = 'ORG' group by cc.contract_id, cc.finance_amount, hbm.enterprise_scale, cc.contract_name, hbm.economic_indu_classify, pq.lease_start_date) t
1 = 1
and t.LEASE_START_DATE <= to_timestamp(#{periodNameN},'yyyy/mm')
) t1, (select t.class_code, t.class_id value_code, t.description value_name, t.parent_class_id parent_tree_node_id from hls_stat_class t where class_usage = 'BIZ_PARTNER' and enabled_flag = 'Y' and t.parent_class_id = 525 and t.description not in ('T-国际组织')) t2 where t2.value_name = t1.economic_indu_classify(+) group by t2.value_name) b group by economic_component, LARGE_SCALE, MEDIUM, SMALL_SIZED, SMALL_only, MINIATURE, MINIATURE_only) union all (select (select '国有控股企业' from dual) economic_component, total, LARGE_SCALE, MEDIUM, SMALL_SIZED, SMALL_only, MINIATURE, MINIATURE_only from (select sum(total) total, sum(LARGE_SCALE) LARGE_SCALE, sum(MEDIUM) MEDIUM, sum(SMALL_SIZED) SMALL_SIZED, sum(SMALL_only) SMALL_only, sum(MINIATURE) MINIATURE, sum(MINIATURE_only) MINIATURE_only from (select economic_component, sum(LARGE_SCALE + MEDIUM + SMALL_SIZED + SMALL_only + MINIATURE + MINIATURE_only) total, LARGE_SCALE, MEDIUM, SMALL_SIZED, SMALL_only, MINIATURE, MINIATURE_only from (select substr(t2.value_name, 3) economic_component, NVL(round(sum(t1.LARGE_SCALE) / 10000, 2), 0) LARGE_SCALE, NVL(round(sum(t1.MEDIUM) / 10000, 2), 0) MEDIUM, NVL(round(sum(t1.SMALL_SIZED) / 10000, 2), 0) SMALL_SIZED, NVL(round(sum(t1.SMALL_only) / 10000, 2), 0) SMALL_only, NVL(round(sum(t1.MINIATURE) / 10000, 2), 0) MINIATURE, NVL(round(sum(t1.MINIATURE_only) / 10000, 2), 0) MINIATURE_only from (select economic_indu_classify, (case when t.enterprise_scale = 'LARGE_SCALE' then t.total_rental end) LARGE_SCALE, (case when t.enterprise_scale = 'MEDIUM' then t.total_rental end) MEDIUM, (case when t.enterprise_scale = 'SMALL_SIZED' and t.finance_amount > 10000000 then t.total_rental end) SMALL_SIZED, (case when t.enterprise_scale = 'SMALL_SIZED' and t.finance_amount < 10000000 then t.total_rental end) SMALL_only, (case when t.enterprise_scale = 'MINIATURE' and t.finance_amount > 10000000 then t.total_rental end) MINIATURE, (case when t.enterprise_scale = 'MINIATURE' and t.finance_amount < 10000000 then t.total_rental end) MINIATURE_only from (select cc.contract_id, cc.finance_amount, sum(ccc.principal - ccc.received_principal) total_rental, hbm.enterprise_scale, cc.contract_name, (SELECT t.description FROM hls_stat_class t WHERE t.class_usage = 'BIZ_PARTNER' AND t.enabled_flag = 'Y' and t.CLASS_ID = (SELECT t.parent_class_id FROM hls_stat_class t WHERE t.class_usage = 'BIZ_PARTNER' AND t.enabled_flag = 'Y' and t.CLASS_ID = hbm.economic_indu_classify)) economic_indu_classify, pq.lease_start_date from con_contract_cashflow ccc, con_contract cc left join prj_quotation pq on cc.quotation_id = pq.quotation_id, hls_bp_master hbm where cc.contract_id = ccc.contract_Id and cc.contract_status = 'INCEPT' and cc.data_class = 'NORMAL' and cc.tenant_id = hbm.bp_id and hbm.bp_class = 'ORG' group by cc.contract_id, cc.finance_amount, hbm.enterprise_scale, cc.contract_name, hbm.economic_indu_classify, pq.lease_start_date) t
1 = 1
and t.LEASE_START_DATE <= to_timestamp(#{periodNameN},'yyyy/mm')
) t1, (select t.class_code, t.class_id value_code, t.description value_name, t.parent_class_id parent_tree_node_id from hls_stat_class t where class_usage = 'BIZ_PARTNER' and enabled_flag = 'Y' and t.parent_class_id = 525 and t.description not in ('T-国际组织')) t2 where t2.value_name = t1.economic_indu_classify(+) group by t2.value_name) b group by economic_component, LARGE_SCALE, MEDIUM, SMALL_SIZED, SMALL_only, MINIATURE, MINIATURE_only)))) t ) t
1=1
and t.economic_component = #{economicComponentN}

select t1.* from ( SELECT t.*,(select b.bp_name from hls_bp_master b where b.bp_id = t.tenant_id)bp_name,(select s.description from sys_user s where s.user_id = t.host_project_manager)host_project_manager_n, (select p.contract_number from prj_project p where p.data_class = 'VIRTUAL_CON' and p.project_id = t.project_id)project_number FROM con_contract t)t1
1=1
and t1.contract_number = #{contractNumber}
and t1.bp_name like concat(concat('%',#{bpName}),'%')
and t1.project_number = #{projectNumber}
and t1.host_project_manager_n like concat(concat('%',#{hostProjectManagerN}),'%')

select v.* , nvl((select max(( CASE hur.RELATION_DOCUMENT_ID WHEN NULL THEN 'N' ELSE 'Y' END )) from hls_user_relationship hur where v.contract_id = hur.RELATION_DOCUMENT_ID and hur.SOURCE_USER_ID = 10001),'N') collectFlag from( select nvl(p.contract_status,'NEW') contract_status, p.company_id, p.contract_amount, (select bp_name from hls_bp_master where bp_id=p.tenant_id) as bp_name, p.contract_id, p.project_id, p.document_type, p.business_type, p.document_category, p.division, p.employee_id, p.floating_range_method, p.inspect_frenquency, p.is_insure, p.lease_start_date, p.penalty_rate, p.prepayment_method, p.tenant_id, p.unit_id, p.contract_number payment_number, pp.contract_number, p.contract_name, p.CREATION_DATE, (select hdt.description from hls_document_type hdt where hdt.business_type=pp.business_type and hdt.document_category=pp.document_category and hdt.document_type=pp.document_type) as document_type_desc, (select s.MEANING from sys_code_value_b_v s where s.CODE = 'CON.CONTRACT_STATUS' and s.code_value = p.contract_status)contract_status_desc, (select pp.project_name from prj_project pp where pp.project_id=p.project_id ) as project_name, (select pp.project_number from prj_project pp where pp.project_id=p.project_id ) as project_number, case when p.document_type in('CONLB','CONL') THEN PP.CONTRACT_NUM ELSE (select ppa.contract_number from prj_project_attachment ppa where ppa.document_name = '融资租赁合同' and ppa.project_id = p.project_id) end as legal_contract_number, p.quotation_id, p.lease_end_date, p.irr, p.xirr, P.FINANCE_AMOUNT, p.lease_item_amount, pp.IS_LOW_RISK, (SELECT h.PAYMENT_REQ_ID FROM CSH_PAYMENT_REQ_HD h, CSH_PAYMENT_REQ_LN l WHERE h.PAYMENT_REQ_ID = l.PAYMENT_REQ_ID AND l.SOURCE_DOC_ID = p.contract_id AND h.PAYMENT_REQ_STATUS = 'APPROVED' and rownum=1) PAYMENT_REQ_ID, (SELECT SUM(NVL(C.RECEIVED_PRINCIPAL, 0)) FROM CON_CONTRACT_CASHFLOW C WHERE C.CF_DIRECTION = 'INFLOW' AND C.CF_STATUS = 'RELEASE' and c.contract_id=p.contract_id AND C.CF_ITEM IN (1, 11, 13 )) received_principal, (SELECT SUM(NVL(C.RECEIVED_INTEREST, 0)) FROM CON_CONTRACT_CASHFLOW C WHERE C.CF_DIRECTION = 'INFLOW' AND C.CF_STATUS = 'RELEASE' and c.contract_id=p.contract_id AND C.CF_ITEM IN (1, 11, 13 )) received_interest
from con_contract p LEFT JOIN hls_division hd on p.division=hd.division and p.company_id = hd.company_id LEFT JOIN prj_project pp on p.project_id = pp.project_id LEFT JOIN (select * from hls_document_status t1 where t1.document_category='CON_CONTRACT') hds on hds.status_code=nvl(p.contract_status,'NEW')) v
1=1
and v.contract_status = #{contractStatus}
and v.project_name like concat(concat('%',#{projectName}),'%')
and v.project_number like concat(concat('%',#{projectNumber}),'%')
and v.project_number like concat(concat('%',#{projectNumberN}),'%')
and v.project_id = #{projectId}
and v.contract_name like concat(concat('%',#{contractName}),'%')
and v.payment_number like concat(concat('%',#{contractNumber}),'%')
and v.bp_name like concat(concat('%',#{bpName}),'%')
and v.contract_amount >= #{financeAmountFrom}
and v.contract_amount <= #{financeAmountTo}
and v.business_type = #{businessType}
and v.company_id = #{companyId}
and v.contract_id = #{contractId}
and v.contract_status = #{contractStatus}
and (v.contract_number like concat(concat('%',#{params}),'%')) or (v.contract_name like concat(concat('%',#{params}),'%')) or (v.bp_name like concat(concat('%',#{params}),'%'))
order by v.CREATION_DATE desc

select v.* , nvl((select max(( CASE hur.RELATION_DOCUMENT_ID WHEN NULL THEN 'N' ELSE 'Y' END )) from hls_user_relationship hur where v.contract_id = hur.RELATION_DOCUMENT_ID and hur.SOURCE_USER_ID = 10001),'N') collectFlag, (v.principal_amount - v.write_off_principal) residual_principal, (v.deposit_amount - v.write_off_deposit) residual_deposit from( select nvl(p.contract_status,'NEW') contract_status, p.company_id,
nvl((SELECT SUM(nvl(ccc.principal, 0)) FROM con_contract_cashflow ccc WHERE ccc.contract_id = p.contract_id AND ccc.cf_item IN (1, 10) AND ccc.cf_status = 'RELEASE'), 0) principal_amount,
nvl((SELECT CASE WHEN q.vatable_prin_flag = 'Y' THEN SUM(nvl(o.write_off_principal, 0)) ELSE ROUND(SUM(nvl(o.write_off_principal, 0) / (1 + p.vat_rate)), 2) END FROM csh_write_off o WHERE o.contract_id = p.contract_id AND o.cf_item IN (1, 10) AND o.reversed_flag = 'N' AND o.write_off_date <= to_date(#{pointInTime},'YYYY-MM-DD')), 0) AS write_off_principal,
nvl((SELECT SUM(nvl(ccc.due_amount, 0)) FROM con_contract_cashflow ccc WHERE ccc.contract_id = p.contract_id AND ccc.cf_item IN (51, 53) AND ccc.cf_status = 'RELEASE'), 0) deposit_amount,
nvl((SELECT SUM(nvl(o.write_off_due_amount, 0)) FROM csh_write_off o WHERE o.contract_id = p.contract_id AND o.cf_item IN (51, 53) AND o.reversed_flag = 'N' AND o.write_off_date <= to_date(#{pointInTime},'YYYY-MM-DD')), 0) write_off_deposit,
(select pq.first_release_date from prj_quotation pq where pq.quotation_id=p.quotation_id)first_release_date, (select ( case when nvl(pq.financial_lease_flag, 'N') = 'N' then '未起租' nvl(pq.financial_lease_flag, 'N') = 'Y' then '起租' end) from prj_quotation pq where pq.source_document_category = 'CON_CONTRACT' and pq.source_Document_Id = p.contract_id)financial_lease_status_n, (select s.description from sys_user s where s.user_id = p.host_project_manager) host_project_manager_n, (select fou.unit_name from fnd_org_unit fou where fou.unit_id = p.host_unit_id) host_unit_name,
p.contract_amount, (select bp_name from hls_bp_master where bp_id=p.tenant_id) as bp_name, p.contract_id, p.project_id, p.document_type, p.business_type, p.document_category, p.division, p.employee_id, p.floating_range_method, p.inspect_frenquency, p.is_insure, p.lease_start_date, p.penalty_rate, p.prepayment_method, p.tenant_id, p.unit_id, p.contract_number payment_number, pp.contract_number, p.contract_name, p.CREATION_DATE, (select hdt.description from hls_document_type hdt where hdt.business_type=pp.business_type and hdt.document_category=pp.document_category and hdt.document_type=pp.document_type) as document_type_desc, case when exists(select 1 from con_contract cc, con_contract_cashflow ccc where cc.FIN_LOAN_INITIAL_LEASE = 'N' and cc.contract_id = ccc.contract_id and ccc.cf_item = 0 and ccc.cf_direction = 'OUTFLOW' and ccc.write_off_flag = 'FULL' and p.contract_id = cc.contract_id) then '已放款' else (select s.MEANING from sys_code_value_b_v s where s.CODE = 'CON.CONTRACT_STATUS' and s.code_value = p.contract_status) end contract_status_desc, ( SELECT s.MEANING FROM sys_code_value_b_v s WHERE s.CODE = 'CON.CONTRACT_STATUS' AND s.code_value = p.contract_status ) AS contract_status_n , (select pp.project_name from prj_project pp where pp.project_id=p.project_id ) as project_name, (select pp.project_number from prj_project pp where pp.project_id=p.project_id ) as project_number, p.finance_amount, (select pq.quotation_id from prj_quotation pq where pq.source_document_id = p.contract_id and pq.source_document_category = 'CON_CONTRACT') quotation_id
from con_contract p LEFT JOIN hls_division hd on p.division=hd.division and p.company_id = hd.company_id LEFT JOIN prj_project pp on p.project_id = pp.project_id LEFT JOIN prj_quotation q on p.quotation_id = q.quotation_id) v
1=1
and v.contract_status_desc = #{contractStatusN}
and v.project_name like concat(concat('%',#{projectName}),'%')
and v.project_number like concat(concat('%',#{projectNumber}),'%')
and v.project_number like concat(concat('%',#{projectNumberN}),'%')
and v.project_id = #{projectId}
and v.contract_name like concat(concat('%',#{contractName}),'%')
and v.payment_number like concat(concat('%',#{contractNumber}),'%')
and v.bp_name like concat(concat('%',#{bpName}),'%')
and v.contract_amount >= #{financeAmountFrom}
and v.contract_amount <= #{financeAmountTo}
and v.business_type = #{businessType}
and v.company_id = #{companyId}
and v.contract_id = #{contractId}
and v.contract_status = #{contractStatus}
and (v.contract_number like concat(concat('%',#{params}),'%')) or (v.contract_name like concat(concat('%',#{params}),'%')) or (v.bp_name like concat(concat('%',#{params}),'%'))
order by v.CREATION_DATE desc

SELECT t1.* FROM ( SELECT ( SELECT tc.CONTRACT_NUMBER FROM con_contract tc WHERE tc.CONTRACT_ID = a.SOURCE_CONTRACT_ID ) contract_number, ( SELECT tc.LEGAL_CONTRACT_NUMBER FROM con_contract tc WHERE tc.CONTRACT_ID = a.SOURCE_CONTRACT_ID ) LEGAL_CONTRACT_NUMBER, a.payment_req_number, a.payment_req_date, a.amount, a.payment_req_id, a.payment_req_status, a.AUTHORITY_RULE_STRING, ( SELECT scvb.meaning FROM sys_code_b scb, sys_code_value_b scvb WHERE scb.CODE = 'HLS.WFL_FUNDING_STATUS' AND scb.code_id = scvb.code_id AND scvb. VALUE = a.payment_req_status ) AS payment_req_status_desc, a.SOURCE_CONTRACT_ID contract_id, ( SELECT tc.contract_name FROM con_contract tc WHERE tc.CONTRACT_ID = a.SOURCE_CONTRACT_ID ) contract_name, ( SELECT tc.contract_number FROM con_contract tc WHERE tc.CONTRACT_ID = a.SOURCE_CONTRACT_ID ) funding_plan_number, a.loan_total_amount, a.description, (select hb.bp_name from hls_bp_master hb where hb.bp_id=a.bp_id) bp_name, a.PROPOSED_LAUNCH_DATE, ( SELECT tc.PROJECT_ID FROM con_contract tc WHERE tc.CONTRACT_ID = a.SOURCE_CONTRACT_ID ) PROJECT_ID, ( SELECT PP.CONTRACT_NUMBER FROM PRJ_PROJECT PP WHERE PP.PROJECT_ID =( SELECT tc.PROJECT_ID FROM con_contract tc WHERE tc.CONTRACT_ID = a.SOURCE_CONTRACT_ID )) VIRTUAL_CONTRACT_NUMBER,
( SELECT hclc.credit_flag FROM PRJ_PROJECT PP, hls_credit_line_chance hclc WHERE PP.chance_id = hclc.chance_id and PP.PROJECT_ID =( SELECT tc.PROJECT_ID FROM con_contract tc WHERE tc.CONTRACT_ID = a.SOURCE_CONTRACT_ID ) ) credit_flag,
( SELECT PP.CONTRACT_NAME FROM PRJ_PROJECT PP WHERE PP.PROJECT_ID =( SELECT tc.PROJECT_ID FROM con_contract tc WHERE tc.CONTRACT_ID = a.SOURCE_CONTRACT_ID )) VIRTUAL_CONTRACT_NAME, ( SELECT pp.COMPANY_SPV FROM prj_project pp WHERE pp.PROJECT_ID =( SELECT tc.PROJECT_ID FROM con_contract tc WHERE tc.CONTRACT_ID = a.SOURCE_CONTRACT_ID )) COMPANY_SPV, ( SELECT t.company_full_name FROM fnd_company t WHERE t.company_id =( SELECT pp.COMPANY_SPV FROM prj_project pp WHERE pp.PROJECT_ID =( SELECT tc.PROJECT_ID FROM con_contract tc WHERE tc.CONTRACT_ID = a.SOURCE_CONTRACT_ID ))) company_spv_n, ( SELECT PP.CURRENCY FROM PRJ_PROJECT PP WHERE PP.PROJECT_ID = ( SELECT tc.PROJECT_ID FROM con_contract tc WHERE tc.CONTRACT_ID = a.SOURCE_CONTRACT_ID ) ) AS currency, ( SELECT fc.currency_name FROM fnd_currency fc WHERE fc.currency_code = ( SELECT PP.CURRENCY FROM PRJ_PROJECT PP WHERE PP.PROJECT_ID = ( SELECT tc.PROJECT_ID FROM con_contract tc WHERE tc.CONTRACT_ID = a.SOURCE_CONTRACT_ID ) )), a.ACTUAL_HD_PAY_AMOUNT,a.ACTUAL_PAY_DATE, (SELECT t2.cashflow_id FROM con_contract_cashflow t2 WHERE a.source_contract_id = t2.contract_id AND t2.cf_item = 0 and rownum=1 ) CASHFLOW_ID, a.created_by, ( SELECT fc.currency_name FROM fnd_currency fc WHERE fc.currency_code = a.currency)currency_n, ( SELECT tc.ASSIST_PROJECT_MANAGER FROM con_contract tc WHERE tc.CONTRACT_ID = a.SOURCE_CONTRACT_ID ) ASSIST_PROJECT_MANAGER FROM csh_payment_req_hd a WHERE a.source_doc_type = 'CON_CONTRACT' ) t1
1=1
and ( t1.created_by = #{authority} or t1.ASSIST_PROJECT_MANAGER = #{authority} or #{request.employeeCode} in('ADMIN') OR exists( select 1 from fnd_org_unit a1,fnd_employee a2,fnd_employee_assigns a3,FND_ORG_POSITION a4 where a3.employee_id=a2.employee_id and a3.unit_id=a1.unit_id and a4.position_id=a3.position_id and a4.chief_position_flag='Y' and employee_code=#{request.employeeCode} AND A1.UNIT_ID IN(select b.unit_id from sys_user_allocation a,fnd_employee_assigns b where a.user_id=t1.created_by AND a.employee_assign_id=b.employee_assign_id)))
and t1.project_id = #{projectId}
and t1.payment_req_id = #{paymentReqId}
and t1.payment_req_number = #{paymentReqNumber}
and t1.bp_name LIKE concat('%',concat(#{bpName},'%') )
and t1.payment_req_status = #{paymentReqStatus}
and t1.loan_total_amount = #{loantotalAmount}
and t1.funding_plan_number = #{fundingPlanNumber}
