SELECT distinct cc.contract_id, cc.penalty_calc_method FROM con_contract_cashflow ccc, con_contract cc WHERE ccc.contract_id = cc.contract_id AND ccc.due_date <= #{dayEndDate} AND ccc.cf_direction = 'INFLOW' AND EXISTS (SELECT 1 FROM con_contract_cashflow t WHERE t.contract_id = cc.contract_id AND t.cf_status = 'RELEASE' AND t.cf_item in (0 , 90) AND t.write_off_flag = 'FULL') AND (ccc.due_amount - nvl((SELECT SUM(nvl(o.write_off_due_amount, 0)) FROM csh_write_off o, csh_transaction ct WHERE o.csh_transaction_id = ct.transaction_id AND o.reversed_flag = 'N' AND ct.reversed_flag = 'N' AND o.cashflow_id = ccc.cashflow_id AND ct.transaction_date <= ccc.due_date),0)) > 0
and cc.contract_id = #{contractId}
group by cc.contract_id, cc.penalty_calc_method

SELECT distinct cc.contract_id, cc.penalty_calc_method FROM con_contract_cashflow ccc, con_contract cc WHERE ccc.contract_id = cc.contract_id AND ccc.due_date <= #{dayEndDate} AND ccc.cf_direction = 'INFLOW' and cc.data_class = 'NORMAL' and cc.contract_number like 'PRJ%' AND EXISTS (SELECT 1 FROM con_contract_cashflow t WHERE t.contract_id = cc.contract_id AND t.cf_status = 'RELEASE' AND t.cf_item in (0 , 90) AND t.write_off_flag = 'FULL') AND (ccc.due_amount - nvl((SELECT SUM(nvl(o.write_off_due_amount, 0)) FROM csh_write_off o, csh_transaction ct WHERE o.csh_transaction_id = ct.transaction_id AND o.reversed_flag = 'N' AND ct.reversed_flag = 'N' AND o.cashflow_id = ccc.cashflow_id AND ct.transaction_date <= ccc.due_date),0)) > 0
and cc.contract_id = #{contractId}
group by cc.contract_id, cc.penalty_calc_method

