(select MIN(cprl.payment_completed_date) FROM csh_payment_req_ln cprl WHERE cprl.payment_req_id = reqhd.payment_req_id AND cprl.payment_completed_date IS NOT NULL) payment_completed_date, nvl((select sum(AMOUNT_PAID) from csh_payment_req_ln cprl where cprl.payment_req_id = reqhd.payment_req_id), 0) as sum_amount_paid, hbmba.bp_id, hbmba.bank_account_num, hbmba.bank_account_name, hbmba.bank_full_name, hbmba.bank_branch_name, (SELECT cba.bank_account_name from csh_bank_account cba where cba.bank_account_id=cc.con_payment_account_id)back_bank_account_name, (SELECT cba.bank_account_num from csh_bank_account cba where cba.bank_account_id=cc.con_payment_account_id)con_payment_account_number, pp.project_number, pp.project_name, (select t.term from hls_credit_line t where t.credit_line_id = (select t1.credit_line_id from prj_project t1 where t1.project_id = cc.project_id))term, (select hci.description from hls_cashflow_item hci where hci.cf_item in (select cc.cf_item from con_contract_cashflow cc where cc.CASHFLOW_ID=reqhd.source_doc_line_id))source_doc_line_id_n, reqhd.source_doc_line_id, (select ch.plan_name from cap_capital_investment_plan_hd ch where ch.plan_head_id=(select cl.plan_head_id from cap_capital_investment_plan_ln cl where cl.plan_line_id=cc.plan_ln_id and rownum=1))plan_name, (select ch.plan_number from cap_capital_investment_plan_hd ch where ch.plan_head_id=(select cl.plan_head_id from cap_capital_investment_plan_ln cl where cl.plan_line_id=cc.plan_ln_id and rownum=1))plan_number, (select sum(nvl(ccc.DUE_AMOUNT, 0)) from con_contract_cashflow ccc where ccc.contract_id = cc.contract_id and ccc.CF_ITEM = 1)total_con_due_amount, (select sum(nvl(ccc.INTEREST, 0)) from con_contract_cashflow ccc where ccc.contract_id = cc.contract_id and ccc.CF_ITEM = 1)total_con_interest, reqhd.pay_amount, reqhd.document_type, hbm.bp_name bp_bank_account_bp_name, hfp.PROPOSED_LAUNCH_DATE, cc.*, reqhd.EMPLOYEE_ID, (select fe.NAME FROM fnd_employee fe WHERE fe.employee_id = reqhd.EMPLOYEE_ID) AS EMPLOYEE_ID_n, reqhd.unit_id, (select fou.unit_name from fnd_org_unit fou where fou.unit_id = reqhd.unit_id) unit_id_n from con_contract cc join prj_project pp on cc.project_id = pp.project_id left join HLS_FUNDING_PLAN hfp on cc.CONTRACT_ID = hfp.CONTRACT_ID left join csh_payment_req_hd reqhd on hfp.funding_plan_id = reqhd.funding_plan_id left join hls_bp_master_bank_account hbmba on hbmba.BANK_ACCOUNT_ID = reqhd.BP_BANK_ACCOUNT_ID left join HLS_BP_MASTER hbm ON hbmba.BP_ID = hbm.BP_ID
