SELECT * FROM ( select rpc.payment_confirm_id, rpc.quotation_id, pq.payment_number, p.contract_number, p.contract_num, p.project_id, p.penalty_ratio, p.loan_initial_lease, ( select scvb.meaning from sys_code_b scb,sys_code_value_b scvb where scb.code = 'INITIAL_LEASE_TYPE' and scb.code_id = scvb.code_id and scvb.value = p.LOAN_INITIAL_LEASE ) loan_initial_lease_n, p.contract_name, p.project_number, p.project_name, p.contract_amount, (select t.company_full_name from fnd_company t where t.company_id=p.company_id) company_id_n,
(SELECT DESCRIPTION value_name FROM hls_document_type hdt WHERE hdt.document_category = 'PRJ_PROJECT' and hdt.BUSINESS_TYPE = p.business_type) as business_type_n, ( SELECT hbm.bp_name FROM hls_bp_master hbm WHERE hbm.bp_id = p.tenant_id ) AS bp_name, ( SELECT s.description FROM sys_user s WHERE s.user_id = p.host_project_manager ) AS host_project_manager_n, ( SELECT s.description FROM sys_user s WHERE s.user_id = p.assist_project_manager ) AS assist_project_manager_n, ( SELECT fou.unit_name FROM fnd_org_unit fou WHERE fou.unit_id = p.unit_id ) AS unit_name, ( SELECT fe.NAME FROM fnd_org_unit fou, fnd_org_position fop, fnd_employee_assigns fea, fnd_employee fe WHERE fou.unit_id = p.unit_id AND fou.unit_id = fop.unit_id AND fou.company_id = p.company_id AND fop.chief_position_flag = 'Y' AND fop.position_id = fea.position_id AND fea.employee_id = fe.employee_id AND fea.PRIMARY_POSITION_FLAG = 'Y' ) AS project_manager_n, rpc.status, (SELECT meaning FROM sys_code_value_b_v v WHERE v.CODE = 'CONT.RENT_PAYMENT_STATUS' AND v.code_value = rpc.status) status_n, rpc.DESCRIPTION, p.approval_number, nvl( p.FALSIFY_CALCULATION_METHOD, 'COMPOUND_INTEREST' ) FALSIFY_CALCULATION_METHOD, ( SELECT scvb.meaning FROM sys_code_b scb, sys_code_value_b scvb WHERE scb.CODE = 'CON.FALSIFY_CALCULATION' AND scb.code_id = scvb.code_id AND scvb. VALUE = nvl( p.FALSIFY_CALCULATION_METHOD, 'COMPOUND_INTEREST' ) ) FALSIFY_CALCULATION_METHOD_N, p.FALSIFY_INTEREST_RATE, p.EARLY_TERMINATION_RATIO, p.EARLY_ALSO_RENT_RATIO, p.STAMP_DUTY, p.ADDED_VALUE_TAX, p.whether_labeling, ( SELECT scvb.meaning FROM sys_code_b scb, sys_code_value_b scvb WHERE scb.CODE = 'SYS.YES_NO' AND scb.code_id = scvb.code_id AND scvb. VALUE = p.whether_labeling ) AS whether_labeling_n, p.floating_range_method, ( SELECT scvb.meaning FROM sys_code_b scb, sys_code_value_b scvb WHERE scb.CODE = 'CON.FLOATING_RANGE_METHOD' AND scb.code_id = scvb.code_id AND scvb. VALUE = p.floating_range_method ) AS floating_range_method_n, p.BANK_ACCOUNT_ID, ( SELECT cb.BANK_ACCOUNT_NAME FROM csh_bank_account cb WHERE cb.ENABLED_FLAG = 'Y' AND cb.BANK_ACCOUNT_ID = p.BANK_ACCOUNT_ID ) BANK_ACCOUNT_ID_n, ( SELECT cb.BANK_BRANCH_NAME FROM csh_bank_account cb WHERE cb.ENABLED_FLAG = 'Y' AND cb.BANK_ACCOUNT_ID = p.BANK_ACCOUNT_ID ) BANK_BRANCH_NAME, ( SELECT cb.BANK_ACCOUNT_NUM FROM csh_bank_account cb WHERE cb.ENABLED_FLAG = 'Y' AND cb.BANK_ACCOUNT_ID = p.BANK_ACCOUNT_ID ) BANK_ACCOUNT_NUM, p.SIGN_DATE, p.SING_ADDR from con_rent_payment_confirm rpc,prj_quotation pq,prj_project p where pq.quotation_id = rpc.quotation_id and rpc.project_id = p.project_id ) v
