SELECT * FROM ( SELECT cc.contract_id, cc.quotation_id, cc.contract_number AS payment_number, p.contract_number, p.project_id, p.contract_name, p.project_number, p.project_name, p.contract_amount, ( SELECT t.company_full_name FROM fnd_company t WHERE t.company_id = p.company_id ) company_id_n, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v.CODE = 'HLS200.LEASING_PRODUCT_DETAIL' AND v.CODE_VALUE = p.business_type ) AS business_type_n, ( SELECT hbm.bp_name FROM hls_bp_master hbm WHERE hbm.bp_id = p.tenant_id ) AS bp_name, ( SELECT s.description FROM sys_user s WHERE s.user_id = p.host_project_manager ) AS host_project_manager_n, ( SELECT s.description FROM sys_user s WHERE s.user_id = p.assist_project_manager ) AS assist_project_manager_n, ( SELECT fou.unit_name FROM fnd_org_unit fou WHERE fou.unit_id = p.unit_id ) AS unit_name, ( SELECT fe.NAME FROM fnd_org_unit fou, fnd_org_position fop, fnd_employee_assigns fea, fnd_employee fe WHERE fou.unit_id = p.unit_id AND fou.unit_id = fop.unit_id AND fou.company_id = p.company_id AND fop.chief_position_flag = 'Y' AND fop.position_id = fea.position_id AND fea.employee_id = fe.employee_id AND fea.PRIMARY_POSITION_FLAG = 'Y' ) AS project_manager_n, p.approval_number, nvl( p.FALSIFY_CALCULATION_METHOD, 'COMPOUND_INTEREST' ) FALSIFY_CALCULATION_METHOD, ( SELECT scvb.meaning FROM sys_code_b scb, sys_code_value_b scvb WHERE scb.CODE = 'CON.FALSIFY_CALCULATION' AND scb.code_id = scvb.code_id AND scvb. VALUE = nvl( p.FALSIFY_CALCULATION_METHOD, 'COMPOUND_INTEREST' ) ) FALSIFY_CALCULATION_METHOD_N, p.FALSIFY_INTEREST_RATE, p.EARLY_TERMINATION_RATIO, p.EARLY_ALSO_RENT_RATIO, p.STAMP_DUTY, p.ADDED_VALUE_TAX, p.whether_labeling, ( SELECT scvb.meaning FROM sys_code_b scb, sys_code_value_b scvb WHERE scb.CODE = 'SYS.YES_NO' AND scb.code_id = scvb.code_id AND scvb. VALUE = p.whether_labeling ) AS whether_labeling_n, p.floating_range_method, ( SELECT scvb.meaning FROM sys_code_b scb, sys_code_value_b scvb WHERE scb.CODE = 'CON.FLOATING_RANGE_METHOD' AND scb.code_id = scvb.code_id AND scvb. VALUE = p.floating_range_method ) AS floating_range_method_n, p.BANK_ACCOUNT_ID, ( SELECT cb.BANK_ACCOUNT_NAME FROM csh_bank_account cb WHERE cb.ENABLED_FLAG = 'Y' AND cb.BANK_ACCOUNT_ID = p.BANK_ACCOUNT_ID ) BANK_ACCOUNT_ID_n, ( SELECT cb.BANK_BRANCH_NAME FROM csh_bank_account cb WHERE cb.ENABLED_FLAG = 'Y' AND cb.BANK_ACCOUNT_ID = p.BANK_ACCOUNT_ID ) BANK_BRANCH_NAME, ( SELECT cb.BANK_ACCOUNT_NUM FROM csh_bank_account cb WHERE cb.ENABLED_FLAG = 'Y' AND cb.BANK_ACCOUNT_ID = p.BANK_ACCOUNT_ID ) BANK_ACCOUNT_NUM FROM con_contract cc, prj_quotation pq, prj_project p WHERE pq.quotation_id = cc.quotation_id AND cc.project_id = p.project_id ) v
1=1
and v.contract_id = #{contractId}

select tab.* from (SELECT cc.contract_id, cc.contract_number, bp.bp_name, ( SELECT s.description FROM sys_user s WHERE s.user_id = pp.host_project_manager ) AS host_project_manager_n FROM con_contract cc, prj_quotation pq, prj_project pp LEFT JOIN ( SELECT ppb.project_id, wm_concat( hls.bp_name ) AS bp_name FROM prj_project_bp ppb, hls_bp_master hls WHERE ppb.bp_id = hls.bp_id AND ppb.BP_TYPE IN ( 'TENANT', 'TENANT_SEC', 'ASSET_TRANSFEROR', 'ACCOUNTS_RECEIVABLE' ) GROUP BY ppb.PROJECT_ID ) bp ON pp.PROJECT_ID = bp.project_id WHERE cc.quotation_id = pq.quotation_id AND cc.project_id = pp.project_id AND pq.payment_status = 'CONFIRM' AND pq.BONDED_LEASE_FLAG = 'Y' )tab
1=1
and tab.contract_number = #{contractNumber}
and tab.bp_name = #{bpName}
and tab.host_project_manager_n = #{hostProjectManagerN}
and tab.contract_id = #{contractId}

SELECT v.*, DATE_ADD( v.approval_date, INTERVAL v.approval_term MONTH ) AS EXPIRE_DATE, (case when sysdate>DATE_ADD( v.approval_date, INTERVAL v.approval_term MONTH ) then 0 else v.prj_finance_amount-nvl(v.con_CONTRACT_AMOUNT_total,0) end ) sign_amount_total FROM ( SELECT pp.COMPANY_ID, pp.APPROVAL_NUMBER, (select sum(p2.lease_item_amount) from prj_project p2 where p2.ref_project_id=pp.REF_PROJECT_ID and p2.CONTRACT_STATUS not in('CANCEL')) con_CONTRACT_AMOUNT_total, ( SELECT q.finance_amount FROM prj_quotation q WHERE q.SOURCE_DOCUMENT_CATEGORY = 'PRJ_PROJECT' AND q.SOURCE_DOCUMENT_ID = pp.ref_project_id and q.document_id = pp.ref_project_id ) prj_finance_amount, ( SELECT q.CREDIT_FLAG FROM prj_project q WHERE q.PROJECT_ID = pp.ref_project_id ) CREDIT_FLAG, ( SELECT scvb.meaning FROM sys_code_b scb, sys_code_value_b scvb WHERE scb.CODE = 'SYS.YES_NO' AND scb.code_id = scvb.code_id AND scvb. VALUE = ( SELECT q.CREDIT_FLAG FROM prj_project q WHERE q.PROJECT_ID = pp.ref_project_id ) ) AS CREDIT_FLAG_n, ( SELECT pa.approval_term FROM prj_project_approval pa WHERE pa.PROJECT_ID = pp.PROJECT_ID ) approval_term, ( SELECT pa.approval_date FROM prj_project_approval pa WHERE pa.PROJECT_ID = pp.PROJECT_ID ) approval_date, ( SELECT fnd.COMPANY_FULL_NAME FROM fnd_company fnd WHERE fnd.COMPANY_ID = pp.COMPANY_ID ) LESSOR_NAME, ( SELECT fou.unit_name FROM fnd_org_unit fou WHERE fou.unit_id = pp.unit_id ) UNIT_NAME, pp.unit_id, ( SELECT hdt.description FROM hls_document_type hdt WHERE hdt.business_type = pp.business_type AND hdt.document_category = pp.document_category AND hdt.document_type = pp.document_type ) AS business_type_n, pp.business_type, pp.PROJECT_NUMBER, pp.CONTRACT_NUMBER, pp.host_project_manager, ( SELECT s.description FROM sys_user s WHERE s.user_id = pp.host_project_manager ) host_project_manager_n, pp.assist_project_manager, ( SELECT s.description FROM sys_user s WHERE s.user_id = pp.assist_project_manager ) assist_project_manager_n, ( SELECT p1.project_name FROM prj_project p1 WHERE p1.PROJECT_ID = pp.REF_PROJECT_ID ) AS project_name, pp.CONTRACT_NAME, /* ( SELECT wm_concat( h.bp_name ) FROM prj_project_bp pb, hls_bp_master h WHERE h.bp_id = pb.bp_id AND pb.bp_type = 'TENANT' AND pb.project_id = pp.project_id ) AS bp_name,*/ ( CASE
WHEN pp.business_type IN ( 'T+N_LEASE_FACTORING', 'T+0_LEASE_FACTORING' ) THEN ( SELECT wm_concat( h.bp_name ) FROM prj_project_bp pb, hls_bp_master h WHERE h.bp_id = pb.bp_id AND pb.bp_type = 'ACCOUNTS_RECEIVABLE' AND pb.project_id = pp.project_id ) WHEN pp.business_type IN ( 'LEASE_WITHOUT_RECOURSE_IN', 'OPERATING_LEASE_WITHOUT_RECOURSE_IN' ) THEN ( SELECT wm_concat( h.bp_name ) FROM prj_project_bp pb, hls_bp_master h WHERE h.bp_id = pb.bp_id AND pb.bp_type = 'ASSET_TRANSFEROR' AND pb.project_id = pp.project_id ) ELSE ( SELECT wm_concat( h.bp_name ) FROM prj_project_bp pb, hls_bp_master h WHERE h.bp_id = pb.bp_id AND pb.bp_type = 'TENANT' AND pb.project_id = pp.project_id ) END ) AS bp_name, ( SELECT p1.IS_LOW_RISK FROM prj_project p1 WHERE p1.PROJECT_ID = pp.REF_PROJECT_ID ) IS_LOW_RISK, ( SELECT scvb.meaning FROM sys_code_b scb, sys_code_value_b scvb WHERE scb.CODE = 'SYS.YES_NO' AND scb.code_id = scvb.code_id AND scvb. VALUE = ( SELECT p1.IS_LOW_RISK FROM prj_project p1 WHERE p1.PROJECT_ID = pp.REF_PROJECT_ID ) ) AS GROUP_CUSTOMERS, ( CASE
WHEN ( SELECT COUNT(*) FROM fct_project_attachment FCT, hls_doc_file_templet DOC WHERE FCT.TEMPLATE_ID = DOC.TEMPLET_ID AND FCT.PROJECT_ID = PP.PROJECT_ID AND DOC.TEMPLET_CODE IN ( 'CON_LEASE', 'CON_LEASE_COM', 'CON_LEASE_BACK1' ) ) = 0 THEN ( SELECT min( FCT.SIGN_DATE ) FROM fct_project_attachment FCT WHERE FCT.PROJECT_ID = PP.PROJECT_ID ) ELSE ( SELECT min( FCT.SIGN_DATE ) FROM fct_project_attachment FCT, hls_doc_file_templet DOC WHERE FCT.TEMPLATE_ID = DOC.TEMPLET_ID AND FCT.PROJECT_ID = PP.PROJECT_ID AND DOC.TEMPLET_CODE IN ( 'CON_LEASE', 'CON_LEASE_COM', 'CON_LEASE_BACK1' ) ) END ) SIGN_DATE, nvl(( SELECT sum( ln.TOTAL_AMOUNT ) FROM acp_invoice_ln ln WHERE ln.CONTRACT_ID = pp.PROJECT_ID ), 0 ) RECEIVED_RECEIPT_AMOUNT, pp.CONTRACT_AMOUNT, (pp.lease_item_amount +(select nvl(sum(h.ACTUAL_HD_PAY_AMOUNT),0) from csh_payment_req_hd h where h.SOURCE_DOC_ID = pp.project_id and h.loan_type = 'TARIFF'))lease_item_amount, (nvl(( SELECT SUM( HD.ACTUAL_HD_PAY_AMOUNT ) FROM csh_payment_req_hd hd WHERE hd.PAYMENT_APPROVED_STATUS = 'PAID' and hd.loan_type != 'TARIFF' AND HD.SOURCE_DOC_ID = PP.PROJECT_ID ), 0 ) +(select nvl(sum(h.ACTUAL_HD_PAY_AMOUNT),0) from csh_payment_req_hd h where h.SOURCE_DOC_ID = pp.project_id and h.loan_type = 'TARIFF'))PAIED_AMOUNT, (pp.lease_item_amount - nvl(( SELECT SUM( HD.ACTUAL_HD_PAY_AMOUNT ) FROM csh_payment_req_hd hd WHERE hd.PAYMENT_APPROVED_STATUS = 'PAID' AND HD.SOURCE_DOC_ID = PP.PROJECT_ID ), 0 ) +(select nvl(sum(h.ACTUAL_HD_PAY_AMOUNT),0) from csh_payment_req_hd h where h.SOURCE_DOC_ID = pp.project_id and h.loan_type = 'TARIFF'))UNPAIED_AMOUNT, (select nvl(( SELECT sc.meaning AS value_name FROM sys_code_value_b_v sc WHERE sc.code = 'FND.INDUSTRY_2' AND sc.code_value = b.economic_indu_classify ), ( SELECT t.description FROM hls_stat_class t WHERE t.class_usage = 'BIZ_PARTNER' AND t.enabled_flag = 'Y' AND t.CLASS_ID = b.economic_indu_classify )) from hls_bp_master b where b.bp_id = pp.tenant_id) economic_indu_classify_n, ( SELECT q.LEASE_ITEM_AMOUNT_ORG FROM prj_quotation q WHERE q.SOURCE_DOCUMENT_ID = pp.project_id AND q.SOURCE_DOCUMENT_CATEGORY = 'PRJ_PROJECT' AND q.DATA_CLASS = 'VIRTUAL_CON' ) LEASE_ITEM_AMOUNT_ORG, ( SELECT f.currency_name FROM prj_quotation q, fnd_currency f WHERE q.SOURCE_DOCUMENT_ID = pp.project_id AND q.SOURCE_DOCUMENT_CATEGORY = 'PRJ_PROJECT' AND f.CURRENCY_CODE = q.CURRENCY AND q.DATA_CLASS = 'VIRTUAL_CON' ) CURRENCY_n FROM prj_project pp WHERE pp.contract_status not in ('APPROVING','NEW','CLOSED') and pp.data_class = 'VIRTUAL_CON') v
1=1
