SELECT sum(v.lease_item_amount) as lease_item_amount_sum, sum(v.paied_amount) as paied_amount_sum, sum(v.unpaied_amount) as unpaied_amount_sum, count(1) as total FROM ( SELECT pp.COMPANY_ID, pp.APPROVAL_NUMBER, (select sum(p2.lease_item_amount) from prj_project p2 where p2.ref_project_id=pp.REF_PROJECT_ID and p2.CONTRACT_STATUS not in('CANCEL')) con_CONTRACT_AMOUNT_total, ( SELECT q.finance_amount FROM prj_quotation q WHERE q.SOURCE_DOCUMENT_CATEGORY = 'PRJ_PROJECT' AND q.SOURCE_DOCUMENT_ID = pp.ref_project_id and q.document_id = pp.ref_project_id ) prj_finance_amount, ( SELECT q.CREDIT_FLAG FROM prj_project q WHERE q.PROJECT_ID = pp.ref_project_id ) CREDIT_FLAG, ( SELECT scvb.meaning FROM sys_code_b scb, sys_code_value_b scvb WHERE scb.CODE = 'SYS.YES_NO' AND scb.code_id = scvb.code_id AND scvb. VALUE = ( SELECT q.CREDIT_FLAG FROM prj_project q WHERE q.PROJECT_ID = pp.ref_project_id ) ) AS CREDIT_FLAG_n, ( SELECT pa.approval_term FROM prj_project_approval pa WHERE pa.PROJECT_ID = pp.PROJECT_ID ) approval_term, ( SELECT pa.approval_date FROM prj_project_approval pa WHERE pa.PROJECT_ID = pp.PROJECT_ID ) approval_date, ( SELECT fnd.COMPANY_FULL_NAME FROM fnd_company fnd WHERE fnd.COMPANY_ID = pp.COMPANY_ID ) LESSOR_NAME, ( SELECT fou.unit_name FROM fnd_org_unit fou WHERE fou.unit_id = pp.unit_id ) UNIT_NAME, pp.unit_id, ( SELECT hdt.description FROM hls_document_type hdt WHERE hdt.business_type = pp.business_type AND hdt.document_category = pp.document_category AND hdt.document_type = pp.document_type ) AS business_type_n, pp.business_type, pp.PROJECT_NUMBER, pp.CONTRACT_NUMBER, pp.host_project_manager, ( SELECT s.description FROM sys_user s WHERE s.user_id = pp.host_project_manager ) host_project_manager_n, pp.assist_project_manager, ( SELECT s.description FROM sys_user s WHERE s.user_id = pp.assist_project_manager ) assist_project_manager_n, ( SELECT p1.project_name FROM prj_project p1 WHERE p1.PROJECT_ID = pp.REF_PROJECT_ID ) AS project_name, pp.CONTRACT_NAME, /* ( SELECT wm_concat( h.bp_name ) FROM prj_project_bp pb, hls_bp_master h WHERE h.bp_id = pb.bp_id AND pb.bp_type = 'TENANT' AND pb.project_id = pp.project_id ) AS bp_name,*/ ( CASE
WHEN pp.business_type IN ( 'T+N_LEASE_FACTORING', 'T+0_LEASE_FACTORING' ) THEN ( SELECT wm_concat( h.bp_name ) FROM prj_project_bp pb, hls_bp_master h WHERE h.bp_id = pb.bp_id AND pb.bp_type = 'ACCOUNTS_RECEIVABLE' AND pb.project_id = pp.project_id ) WHEN pp.business_type IN ( 'LEASE_WITHOUT_RECOURSE_IN', 'OPERATING_LEASE_WITHOUT_RECOURSE_IN' ) THEN ( SELECT wm_concat( h.bp_name ) FROM prj_project_bp pb, hls_bp_master h WHERE h.bp_id = pb.bp_id AND pb.bp_type = 'ASSET_TRANSFEROR' AND pb.project_id = pp.project_id ) ELSE ( SELECT wm_concat( h.bp_name ) FROM prj_project_bp pb, hls_bp_master h WHERE h.bp_id = pb.bp_id AND pb.bp_type = 'TENANT' AND pb.project_id = pp.project_id ) END ) AS bp_name, ( SELECT p1.IS_LOW_RISK FROM prj_project p1 WHERE p1.PROJECT_ID = pp.REF_PROJECT_ID ) IS_LOW_RISK, ( SELECT scvb.meaning FROM sys_code_b scb, sys_code_value_b scvb WHERE scb.CODE = 'SYS.YES_NO' AND scb.code_id = scvb.code_id AND scvb. VALUE = ( SELECT p1.IS_LOW_RISK FROM prj_project p1 WHERE p1.PROJECT_ID = pp.REF_PROJECT_ID ) ) AS GROUP_CUSTOMERS, ( CASE
WHEN ( SELECT COUNT(*) FROM fct_project_attachment FCT, hls_doc_file_templet DOC WHERE FCT.TEMPLATE_ID = DOC.TEMPLET_ID AND FCT.PROJECT_ID = PP.PROJECT_ID AND DOC.TEMPLET_CODE IN ( 'CON_LEASE', 'CON_LEASE_COM', 'CON_LEASE_BACK1' ) ) = 0 THEN ( SELECT min( FCT.SIGN_DATE ) FROM fct_project_attachment FCT WHERE FCT.PROJECT_ID = PP.PROJECT_ID ) ELSE ( SELECT min( FCT.SIGN_DATE ) FROM fct_project_attachment FCT, hls_doc_file_templet DOC WHERE FCT.TEMPLATE_ID = DOC.TEMPLET_ID AND FCT.PROJECT_ID = PP.PROJECT_ID AND DOC.TEMPLET_CODE IN ( 'CON_LEASE', 'CON_LEASE_COM', 'CON_LEASE_BACK1' ) ) END ) SIGN_DATE, nvl(( SELECT sum( ln.TOTAL_AMOUNT ) FROM acp_invoice_ln ln WHERE ln.CONTRACT_ID = pp.PROJECT_ID ), 0 ) RECEIVED_RECEIPT_AMOUNT, pp.CONTRACT_AMOUNT, (pp.lease_item_amount +(select nvl(sum(h.ACTUAL_HD_PAY_AMOUNT),0) from csh_payment_req_hd h where h.SOURCE_DOC_ID = pp.project_id and h.loan_type = 'TARIFF'))lease_item_amount, (nvl(( SELECT SUM( HD.ACTUAL_HD_PAY_AMOUNT ) FROM csh_payment_req_hd hd WHERE hd.PAYMENT_APPROVED_STATUS = 'PAID' and hd.loan_type != 'TARIFF' AND HD.SOURCE_DOC_ID = PP.PROJECT_ID ), 0 ) +(select nvl(sum(h.ACTUAL_HD_PAY_AMOUNT),0) from csh_payment_req_hd h where h.SOURCE_DOC_ID = pp.project_id and h.loan_type = 'TARIFF'))PAIED_AMOUNT, (pp.lease_item_amount - nvl(( SELECT SUM( HD.ACTUAL_HD_PAY_AMOUNT ) FROM csh_payment_req_hd hd WHERE hd.PAYMENT_APPROVED_STATUS = 'PAID' AND HD.SOURCE_DOC_ID = PP.PROJECT_ID ), 0 ) +(select nvl(sum(h.ACTUAL_HD_PAY_AMOUNT),0) from csh_payment_req_hd h where h.SOURCE_DOC_ID = pp.project_id and h.loan_type = 'TARIFF'))UNPAIED_AMOUNT, (select nvl(( SELECT sc.meaning AS value_name FROM sys_code_value_b_v sc WHERE sc.code = 'FND.INDUSTRY_2' AND sc.code_value = b.economic_indu_classify ), ( SELECT t.description FROM hls_stat_class t WHERE t.class_usage = 'BIZ_PARTNER' AND t.enabled_flag = 'Y' AND t.CLASS_ID = b.economic_indu_classify )) from hls_bp_master b where b.bp_id = pp.tenant_id) economic_indu_classify_n, ( SELECT q.LEASE_I