select v.* from (select cc.CONTRACT_ID, cc.PROJECT_ID, cc.COMPANY_ID, (select f.COMPANY_FULL_NAME from fnd_company f where f.COMPANY_ID = cc.COMPANY_ID)LESSOR_NAME, ((select nvl(( SELECT sc.meaning AS value_name FROM sys_code_value_b_v sc WHERE sc.code = 'FND.INDUSTRY_2' AND sc.code_value = b.economic_indu_classify ), ( SELECT t.description FROM hls_stat_class t WHERE t.class_usage = 'BIZ_PARTNER' AND t.enabled_flag = 'Y' AND t.CLASS_ID = b.economic_indu_classify )) from hls_bp_master b where b.bp_id = cc.tenant_id)) economic_indu_classify_n, pp.CONTRACT_NUMBER, cc.BUSINESS_TYPE, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v.CODE = 'HLS200.LEASING_PRODUCT_DETAIL' AND v.CODE_VALUE = cc.business_type ) AS business_type_n,
pp.PROJECT_NAME, cc.UNIT_ID, (select fou.unit_name from fnd_org_unit fou where fou.unit_id=cc.unit_id) as unit_name, cc.HOST_PROJECT_MANAGER, ( SELECT s.description FROM sys_user s WHERE s.user_id = cc.host_project_manager ) host_project_manager_n, cc.ASSIST_PROJECT_MANAGER, ( SELECT s.description FROM sys_user s WHERE s.user_id = cc.assist_project_manager ) assist_project_manager_n, cc.CONTRACT_NAME, cc.TENANT_ID, CASE
WHEN cc.BUSINESS_TYPE in('T+N_LEASE_FACTORING','T+0_LEASE_FACTORING') THEN ( SELECT wm_concat(b.bp_name) FROM hls_bp_master b ,prj_project_bp hclcb WHERE cc.PROJECT_ID = hclcb.PROJECT_ID and b.bp_id = hclcb.bp_id and hclcb.bp_type = 'ACCOUNTS_RECEIVABLE' ) WHEN cc.BUSINESS_TYPE in('LEASE_WITHOUT_RECOURSE_IN','OPERATING_LEASE_WITHOUT_RECOURSE_IN') THEN ( SELECT wm_concat(b.bp_name) FROM hls_bp_master b ,prj_project_bp hclcb WHERE cc.PROJECT_ID = hclcb.PROJECT_ID and b.bp_id = hclcb.bp_id and hclcb.bp_type = 'ASSET_TRANSFEROR' ) ELSE ( SELECT wm_concat(b.bp_name) FROM hls_bp_master b ,prj_project_bp hclcb WHERE cc.PROJECT_ID = hclcb.PROJECT_ID and b.bp_id = hclcb.bp_id and hclcb.bp_type = 'TENANT' ) END AS bp_name, pp.IS_LOW_RISK, ( select scvb.meaning from sys_code_b scb,sys_code_value_b scvb where scb.code = 'SYS.YES_NO' and scb.code_id = scvb.code_id and scvb.value = pp.is_low_risk ) as GROUP_CUSTOMERS_N,
case when (SELECT FCT.SIGN_DATE FROM fct_project_attachment FCT,hls_doc_file_templet DOC WHERE FCT.MAJOR_CON_FLAG='Y' AND FCT.TEMPLATE_ID=DOC.TEMPLET_ID AND DOC.TEMPLET_CODE IN ('CON_LEASE','CON_LEASE_COM','CON_LEASE_BACK1') and FCT.PROJECT_ID = cc.PROJECT_ID and rownum=1 ORDER BY FCT.PROJECT_ATTACHMENT_ID desc ) is null then (select min(fpat.SIGN_DATE) from fct_project_attachment fpat where fpat.PROJECT_ID = cc.PROJECT_ID)
else (SELECT FCT.SIGN_DATE FROM fct_project_attachment FCT,hls_doc_file_templet DOC WHERE FCT.MAJOR_CON_FLAG='Y' AND FCT.TEMPLATE_ID=DOC.TEMPLET_ID AND DOC.TEMPLET_CODE IN ('CON_LEASE','CON_LEASE_COM','CON_LEASE_BACK1') and FCT.PROJECT_ID = cc.PROJECT_ID ORDER BY FCT.PROJECT_ATTACHMENT_ID desc and rownum=1) end as SIGN_DATE,
cc.CONTRACT_AMOUNT, pp.finance_amount, pp.lease_item_amount, CASE WHEN ( SELECT COUNT(1) FROM prj_quotation pq WHERE pq.SOURCE_DOCUMENT_ID = cc.PROJECT_ID AND pq.LEASE_ITEM_AMOUNT_ORG = pp.CONTRACT_AMOUNT AND pq.DATA_CLASS = 'CONTRACT_PLAN' ) = 1 THEN '一次' ELSE '分批' END AS PAY_TYPES,
pq.PAYMENT_NUMBER, (select sum(c.due_amount) from con_contract_cashflow c where c.contract_id = cc.contract_id and c.cf_item = 3 and c.cf_status = 'RELEASE' ) LEASE_MGT_FEE, (select sum(c.due_amount) from con_contract_cashflow c where c.contract_id = cc.contract_id and c.cf_item = 51 and c.cf_status = 'RELEASE' )DEPOSIT, pq.LEASE_START_DATE, (select pqc.DUE_DATE from con_contract_cashflow pqc where pqc.CONTRACT_ID = cc.CONTRACT_ID and pqc.CF_ITEM = 1 order by pqc.CASHFLOW_ID desc and rownum=1)LEASE_END_DATE, ( CASE WHEN (select count(1) from con_rent_payment_confirm tc where tc.contract_id = cc.contract_id and tc.PAYMENT_DISCHARGE_ID is not null) > 0 THEN pq.lease_item_amount ELSE ( SELECT max(cprh.ACTUAL_HD_PAY_AMOUNT) FROM csh_payment_req_hd cprh, csh_payment_req_ln cprl, con_contract_cashflow pqc WHERE cprh.SOURCE_DOC_ID = cc.PROJECT_ID AND cprh.SOURCE_DOC_TYPE = 'CON_CONTRACT' AND cprl.PAYMENT_REQ_ID = cprh.PAYMENT_REQ_ID AND cprl.SOURCE_DOC_LINE_ID = pqc.CASHFLOW_ID AND pqc.contract_id = cc.contract_id ) END ) ACTUAL_HD_PAY_AMOUNT,
(select wm_concat(distinct cprl.BP_BANK_ACCOUNT_NAME) from csh_payment_req_ln cprl,csh_payment_req_hd cprh where cprh.SOURCE_DOC_ID = cc.PROJECT_ID and cprh.SOURCE_DOC_TYPE='CON_CONTRACT' and cprl.PAYMENT_REQ_ID = cprh.PAYMENT_REQ_ID )BP_BANK_ACCOUNT_NAME,
(select wm_concat(distinct cprl.BP_BANK_ACCOUNT_NUM) from csh_payment_req_ln cprl,csh_payment_req_hd cprh where cprh.SOURCE_DOC_ID = cc.PROJECT_ID and cprh.SOURCE_DOC_TYPE='CON_CONTRACT' and cprl.PAYMENT_REQ_ID = cprh.PAYMENT_REQ_ID )BP_BANK_ACCOUNT_NUM,
(select wm_concat(distinct cprl.BP_BANK_BRANCH_NAME) from csh_payment_req_ln cprl,csh_payment_req_hd cprh where cprh.SOURCE_DOC_ID = cc.PROJECT_ID and cprh.SOURCE_DOC_TYPE='CON_CONTRACT' and cprl.PAYMENT_REQ_ID = cprh.PAYMENT_REQ_ID )BP_BANK_BRANCH_NAME,
case when (pq.LEASE_TERM/12*10000%10000>0) then concat(convert(pq.LEASE_TERM/12,decimal(2,1)),'年',pq.LEASE_TIMES,'期') else concat(convert(pq.LEASE_TERM/12,decimal(2,0)),'年',pq.LEASE_TIMES,'期') end as YEAR_TIMES, pq.INT_RATE, pq.IRR, cc.CONTRACT_STATUS, pq.XIRR, case when pq.BONDED_LEASE_FLAG = 'Y' then ( SELECT SUM( nvl( c.NET_PRINCIPAL, 0 )) FROM con_contract_cashflow c WHERE c.contract_id = cc.contract_id AND c.WRITE_OFF_FLAG = 'NOT' AND c.cf_status = 'RELEASE' ) else ( SELECT SUM( nvl( c.PRINCIPAL, 0 ) - nvl( c.RECEIVED_PRINCIPAL,0 ) ) FROM con_contract_cashflow c WHERE c.contract_id = cc.contract_id AND c.cf_status = 'RELEASE' ) end AS SURPLUS_PRINCIPAL, pq.LEASE_CHARGE_RATIO from con_contract cc,prj_project pp,prj_quotation pq where cc.PROJECT_ID = pp.PROJECT_ID and cc.QUOTATION_ID = pq.QUOTATION_ID AND EXISTS ( SELECT 1 FROM csh_payment_req_hd hd WHERE hd.PAYMENT_APPROVED_STATUS = 'PAID' AND hd.SOURCE_CONTRACT_ID = cc.contract_id ))v
