SELECT v.* FROM ( SELECT pp.COMPANY_ID, ( SELECT fnd.COMPANY_FULL_NAME FROM fnd_company fnd WHERE fnd.COMPANY_ID = pp.COMPANY_ID ) LESSOR_NAME, ( SELECT fou.unit_name FROM fnd_org_unit fou WHERE fou.unit_id = pp.unit_id ) UNIT_NAME, pp.unit_id, ( SELECT hdt.description FROM hls_document_type hdt WHERE hdt.business_type = pp.business_type AND hdt.document_category = pp.document_category AND hdt.document_type = pp.document_type ) AS business_type_n, pp.business_type, pp.PROJECT_NUMBER, pp.CONTRACT_NUMBER, pp.host_project_manager, ( SELECT s.description FROM sys_user s WHERE s.user_id = pp.host_project_manager ) host_project_manager_n, pp.assist_project_manager, ( SELECT s.description FROM sys_user s WHERE s.user_id = pp.assist_project_manager ) assist_project_manager_n, pp.PROJECT_NAME, a.APPROVAL_NUMBER, a.approval_term, a.approval_date, a.APPROVAL_NOTE, pp.CONTRACT_NAME, ( CASE WHEN pp.business_type IN ( 'T+N_LEASE_FACTORING', 'T+0_LEASE_FACTORING' ) THEN ( SELECT wm_concat(h.bp_name) FROM prj_project_bp pb, hls_bp_master h WHERE h.bp_id = pb.bp_id AND pb.bp_type = 'ACCOUNTS_RECEIVABLE' AND pb.project_id = pp.project_id ) WHEN pp.business_type IN ( 'LEASE_WITHOUT_RECOURSE_IN', 'OPERATING_LEASE_WITHOUT_RECOURSE_IN' ) THEN ( SELECT wm_concat(h.bp_name) FROM prj_project_bp pb, hls_bp_master h WHERE h.bp_id = pb.bp_id AND pb.bp_type = 'ASSET_TRANSFEROR' AND pb.project_id = pp.project_id ) ELSE ( SELECT wm_concat(h.bp_name) FROM prj_project_bp pb, hls_bp_master h WHERE h.bp_id = pb.bp_id AND pb.bp_type = 'TENANT' AND pb.project_id = pp.project_id ) END ) AS bp_name, pp.IS_LOW_RISK, ( SELECT scvb.meaning FROM sys_code_b scb, sys_code_value_b scvb WHERE scb. CODE = 'SYS.YES_NO' AND scb.code_id = scvb.code_id AND scvb. VALUE = pp.IS_LOW_RISK ) AS GROUP_CUSTOMERS, ( CASE WHEN nvl(a.FINANCE_AMOUNT_HIS, 0) > 0 THEN a.FINANCE_AMOUNT_HIS ELSE pp.FINANCE_AMOUNT END ) FINANCE_AMOUNT, ( CASE WHEN nvl(a.LEASE_TERM_HIS, 0) > 0 THEN a.LEASE_TERM_HIS ELSE ( SELECT PQ.LEASE_TERM FROM prj_quotation pq WHERE pq.SOURCE_DOCUMENT_ID = pp.project_id AND pq.SOURCE_DOCUMENT_CATEGORY = 'PRJ_PROJECT' AND pq.data_class = 'PRJ_PROJECT_INVEST' ) END ) LEASE_TERM, ( CASE WHEN nvl(a.LEASE_TERM_HIS, 0) > 0 THEN a.INT_RATE_HIS ELSE ( SELECT PQ.INT_RATE FROM prj_quotation pq WHERE pq.SOURCE_DOCUMENT_ID = pp.project_id AND pq.SOURCE_DOCUMENT_CATEGORY = 'PRJ_PROJECT' AND pq.data_class = 'PRJ_PROJECT_INVEST' ) END ) INT_RATE, a.CHARGE_METHOD, a.GUAR_METHOD, a.DEPOSIT_METHOD, a.FOUNDING_METHOD, a.PAYMENT_METHOD, a.REPAYMENT_METHOD, pp.PROJECT_ID, ( SELECT wm_concat( aa.APPROVAL_SEQ, '、', ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v. CODE = 'APPROVAL_TYPE' AND v.code_value = aa.CONDITION_TYPE ), ':', aa.CONDITION_CONTENT, '\n' SEPARATOR '' ) FROM prj_approval_condition aa WHERE aa.APPROVAL_ID = a.APPROVAL_ID AND aa.approval_type = 'BEFORE' ) approval_note_newa, ( SELECT wm_concat( aa.APPROVAL_SEQ, '、', ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v. CODE = 'APPROVAL_TYPE' AND v.code_value = aa.CONDITION_TYPE ), ':', aa.CONDITION_CONTENT, '\n' SEPARATOR '' ) FROM prj_approval_condition aa WHERE aa.approval_id = a.approval_id AND aa.approval_type = 'AFTER' ) approval_note_newb, ( SELECT wm_concat( aa.APPROVAL_SEQ, '、', ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v. CODE = 'APPROVAL_TYPE' AND v.code_value = aa.CONDITION_TYPE ), ':', aa.CONDITION_CONTENT, '\n' SEPARATOR '' ) FROM prj_approval_condition aa WHERE aa.approval_id = a.approval_id AND aa.approval_type = 'OTHER' ) approval_note_newc FROM prj_project pp, prj_project_approval a WHERE pp.REF_PROJECT_ID IS NULL AND pp.project_status in ('APPROVED','PENDING') AND pp.data_class = 'NORMAL' AND pp.project_id = a.project_id AND a.data_class IN ('NORMAL', 'HISTORY') ) v
