oject_id )* ( SELECT ail.tax_type_rate FROM acp_invoice_ln ail WHERE ail.CONTRACT_ID = pp.project_id and rownum=1 )/(1+ ( SELECT ail.tax_type_rate FROM acp_invoice_ln ail WHERE ail.CONTRACT_ID = pp.project_id and rownum=1)) TAX_AMOUNT, ( SELECT ail.tax_type_rate FROM acp_invoice_ln ail WHERE ail.CONTRACT_ID = pp.project_id and rownum=1 ) tax_type_rate, ( SELECT nvl(sum( ail.Total_AMOUNT ),0) FROM acp_invoice_ln ail WHERE ail.CONTRACT_ID = pp.project_id ) RECEIVED_RECEIPT_AMOUNT, ( SELECT SUM( HD.LOAN_TOTAL_AMOUNT ) FROM csh_payment_req_hd HD WHERE HD.SOURCE_DOC_ID = pp.project_id AND HD.PAYMENT_APPROVED_STATUS = 'PAID' ) - ( SELECT nvl(sum( ail.Total_AMOUNT ),0) FROM acp_invoice_ln ail WHERE ail.CONTRACT_ID = pp.project_id ) UNRECEIVED_RECEIPT_AMOUNT, (Select wm_concat(pc.CONDITION_CONTENT) from prj_approval_condition pc where pc.project_id=pp.ref_project_id and pc.CONDITION_TYPE='TYPE_15') RECEIPT_REQUEST FROM prj_project pp WHERE pp.data_class = 'VIRTUAL_CON' AND pp.data_type = 'NORMAL' and pp.business_type IN ('LEASE','UNION_LEASE','ENTRUST_LEASE') and EXISTS (select 1 from csh_payment_req_hd hd,con_contract cc where hd.SOURCE_CONTRACT_ID=cc.CONTRACT_ID and cc.project_id=pp.project_id and hd.PAYMENT_APPROVED_STATUS='PAID') ) v
