select * from( select cc.contract_id, (select ppa.contract_number from prj_project_attachment ppa where ppa.document_name = '融资租赁合同' and ppa.project_id = pp.project_id) contract_num, cc.contract_name, pp.host_unit_id, (select fou.unit_name from fnd_org_unit fou where fou.unit_id = pp.host_unit_id) host_unit_name, pp.host_project_manager, (select su.description from sys_user su where su.user_id = pp.host_project_manager) host_project_manager_n, pp.tenant_id, (select hbm.bp_name from hls_bp_master hbm where hbm.bp_id = pp.tenant_id) bp_name, cc.sign_date, extract(day from (select max(ccc.fin_income_date) from con_contract_cashflow ccc where ccc.contract_id = cc.contract_id and ccc.cf_item in (1) and ccc.cf_status != 'BLOCK') - cc.sign_date) performance_days, pq.lease_start_date, cc.contract_amount, (select cprh.loan_total_amount from csh_payment_req_hd cprh where cprh.source_contract_id = cc.contract_id and cprh.PAYMENT_TYPE = 'PAYMENT' and cprh.payment_req_status in ('APPROVED')) loan_total_amount, case when exists(select distinct 1 from con_contract_cashflow ccc where ccc.contract_id = cc.contract_id and ccc.cf_item in (1) and ccc.cf_status != 'BLOCK' and ccc.due_date < sysdate and (nvl(ccc.received_amount ,0)!= ccc.due_amount)) then '否' else '是' end performance_status, '截止'||nvl(#{deadline},to_char(sysdate,'yyyy-mm-dd'))||',已收到租金回收款项'|| (select nvl(sum(cwo.write_off_due_amount),0) from csh_write_off cwo, csh_transaction ct where cwo.csh_transaction_id = ct.transaction_id and cwo.contract_id = cc.contract_id and ct.transaction_type = 'RECEIPT' and cwo.reversed_flag = 'N' and cwo.CF_ITEM in (1) and to_char(ct.transaction_date,'yyyy-mm-dd') < nvl(#{deadline},to_char(sysdate,'yyyy-mm-dd'))) ||'元' performance, (select ppa.contract_number from prj_project_attachment ppa where ppa.document_name = '融资租赁合同' and ppa.project_id = pp.project_id) rental_contract_number, (select ppa.signed_date from prj_project_attachment ppa where ppa.document_name = '融资租赁合同' and ppa.project_id = pp.project_id) rental_contract_sign_date, (select ppa.contract_number from prj_project_attachment ppa where ppa.document_name = '租赁物转让协议' and ppa.project_id = pp.project_id) lease_agreement_number, (select ppa.signed_date from prj_project_attachment ppa where ppa.document_name = '租赁物转让协议' and ppa.project_id = pp.project_id) lease_agreement_sign_date, (select ppa.contract_number from prj_project_attachment ppa where ppa.document_name = '买卖合同' and ppa.project_id = pp.project_id) sales_contract_number, (select ppa.signed_date from prj_project_attachment ppa where ppa.document_name = '买卖合同' and ppa.project_id = pp.project_id) sales_contract_sign_date
from con_contract cc, prj_project pp, prj_quotation pq where cc.project_id = pp.project_id and cc.quotation_id = pq.quotation_id and cc.data_class = 'NORMAL' and cc.contract_status in('INCEPT','PENDING') and pp.credit_flag != 'Y' )t
and t.contract_num like concat('%', concat(#{contractNum},'%'))
and t.contract_name like concat('%', concat(#{contractName},'%'))
and t.rental_contract_number like concat('%', concat(#{rentalContractNumber},'%'))
and t.host_project_manager_n like concat('%', concat(#{hostProjectManagerN},'%'))
and t.performance_status like concat('%', concat(#{performanceStatus},'%'))
and to_char(t.sign_date,'yyyy-mm-dd') > #{signDateFrom}
and to_char(t.sign_date,'yyyy-mm-dd') < #{signDateTo}
