decode((SELECT COUNT(*) FROM con_confirm_batch ccb, con_business_confirm cbc WHERE ccb.batch_id = cbc.batch_id AND cbc.contract_id = cc.contract_id AND ccb.refresh_status = 'REFRESH' AND ccb.batch_code NOT LIKE 'QRH-J-%'), 0, DECODE((SELECT COUNT(*) FROM con_confirm_batch ccb, con_business_confirm cbc WHERE ccb.batch_id = cbc.batch_id AND cbc.contract_id = cc.contract_id AND cbc.STATUS = 'CREATED' AND ccb.batch_code NOT LIKE 'QRH-J-%'), 0, 'UNCREATED', 'CREATED'), 'CONFIRM') AS business_confirm_status, (SELECT v.meaning AS value_name FROM sys_code_value_b_v v WHERE v.code = 'BUSINESS_CONFIRM_STATUS' AND v.code_value = decode((SELECT COUNT(*) FROM con_confirm_batch ccb, con_business_confirm cbc WHERE ccb.batch_id = cbc.batch_id AND cbc.contract_id = cc.contract_id AND ccb.refresh_status = 'REFRESH' AND ccb.batch_code NOT LIKE 'QRH-J-%'), 0, DECODE((SELECT COUNT(*) FROM con_confirm_batch ccb, con_business_confirm cbc WHERE ccb.batch_id = cbc.batch_id AND cbc.contract_id = cc.contract_id AND cbc.STATUS = 'CREATED' AND ccb.batch_code NOT LIKE 'QRH-J-%'), 0, 'UNCREATED', 'CREATED'), 'CONFIRM')) AS business_confirm_status_n, decode((SELECT COUNT(*) FROM con_confirm_batch ccb, con_business_confirm cbc WHERE ccb.batch_id = cbc.batch_id AND cbc.contract_id = cc.contract_id AND ccb.refresh_status = 'REFRESH' AND ccb.batch_code LIKE 'QRH-J-%'), 0, DECODE((SELECT COUNT(*) FROM con_confirm_batch ccb, con_business_confirm cbc WHERE ccb.batch_id = cbc.batch_id AND cbc.contract_id = cc.contract_id AND cbc.DEALER_STATUS = 'CREATED' AND ccb.batch_code LIKE 'QRH-J-%'), 0, 'UNCREATED', 'CREATED'), 'CONFIRM') AS dealer_biz_cfm_status, (SELECT v.meaning AS value_name FROM sys_code_value_b_v v WHERE v.code = 'BUSINESS_CONFIRM_STATUS' AND v.code_value = decode((SELECT COUNT(*) FROM con_confirm_batch ccb, con_business_confirm cbc WHERE ccb.batch_id = cbc.batch_id AND cbc.contract_id = cc.contract_id AND ccb.refresh_status = 'REFRESH' AND ccb.batch_code LIKE 'QRH-J-%'), 0, DECODE((SELECT COUNT(*) FROM con_confirm_batch ccb, con_business_confirm cbc WHERE ccb.batch_id = cbc.batch_id AND cbc.contract_id = cc.contract_id AND cbc.DEALER_STATUS = 'CREATED' AND ccb.batch_code LIKE 'QRH-J-%'), 0, 'UNCREATED', 'CREATED'), 'CONFIRM')) AS dealer_biz_cfm_status_n,
cc.creation_date, (Select Max(ccb.batch_code) From con_business_confirm cbc, con_confirm_batch ccb Where ccb.last_update_date = (Select Max(ccb2.last_update_date) From con_business_confirm cbc2, con_confirm_batch ccb2 Where cbc.contract_id = cbc2.contract_id And ccb2.batch_id = cbc2.batch_id And ccb2.refresh_status = 'REFRESH') And cbc.contract_id = cc.contract_id And ccb.batch_id = cbc.batch_id And ccb.refresh_status = 'REFRESH') As RETRIEVED_BATCH_NUMBER, cc.pledge_flag, (Select v.meaning From sys_code_value_b_v v Where v.CODE = 'SYS.YES_NO' And v.code_value = cc.pledge_flag) pledge_flag_n,
NVL(ccr.CHANGE_REQ_DATE, cc.LEASE_END_DATE) DUE_DATE, Case cc.CONTRACT_STATUS When 'TERMINATE' Then Case ccr.CHANGE_TYPE When 'REPO' Then 'REPURCHASE_CHASE' When 'PREPAYMENT' Then 'EARLY_SERRLEMENT' Else 'NORMAL_SETTLEMENT' End Else Null End CHANGE_TYPE, Case cc.CONTRACT_STATUS When 'TERMINATE' Then Case ccr.CHANGE_TYPE When 'REPO' Then '回购' When 'PREPAYMENT' Then '提前结清' Else '正常结清' End Else Null End CHANGE_TYPE_N, cc.TERMINATION_DATE, nvl( cc.contract_text_status, 'UNCREATED' ), ( SELECT v.meaning AS value_name FROM sys_code_value_b_v v WHERE v.code = 'CONTRACT_TEXT_STATUS' AND v.code_value = nvl( cc.contract_text_status, 'UNCREATED' ) ) AS contract_text_status_n, ( SELECT scvb.meaning FROM sys_code_b scb, sys_code_value_b scvb WHERE scb.code = 'SIGN_METHOD' AND scb.code_id = scvb.code_id AND scvb.value = cc.sign_type ) sign_type_n, cc.sign_type, (select hbmr.bear_guarantee_flag from hls_credit_line hcl, hls_bp_master_reply hbmr where cc.manufacturer_id = hcl.bp_id and hbmr.credit_line_id = hcl.credit_line_id and hbmr.latest_flag = 'Y') bear_guarantee_flag, (select (SELECT v.meaning FROM sys_code_value_b_v v WHERE v.CODE = 'SYS.YES_NO' AND v.code_value = hbmr.bear_guarantee_flag) from hls_credit_line hcl, hls_bp_master_reply hbmr where cc.manufacturer_id = hcl.bp_id and hbmr.credit_line_id = hcl.credit_line_id and hbmr.latest_flag = 'Y') bear_guarantee_flag_n, pp.partners_contract_status, (select sv.MEANING from sys_code_value_b_v sv where sv.CODE = 'SY_CONTRACT_STATUS' and sv.code_value = pp.partners_contract_status) partners_contract_status_n, (SELECT v.meaning AS value_name FROM sys_code_value_b_v v WHERE v.code = 'PRJ_EQUIPMENT_TYPE' and v.code_value=cc.second_hand_flag) second_hand_flag_n, cc.payment_bp_type, (SELECT v.meaning AS value_name FROM sys_code_value_b_v v WHERE v.CODE = 'PAYMENT_BP_TYPE' and v.code_value = cc.payment_bp_type) payment_bp_type_n, cc.PAYMENT_BP_ID, (SELECT m.bp_name FROM hls_bp_master m WHERE m.bp_id = cc.PAYMENT_BP_ID) AS PAYMENT_BP_ID_N, (SELECT fe.mobile FROM fnd_employee fe WHERE fe.employee_id = decode((select fe.COMPANY_ID from FND_EMPLOYEE fe,sys_user su where su.user_id=pp.CREATED_BY and su.DESCRIPTION=fe.name),'248', (select fe.employee_id from FND_EMPLOYEE fe,sys_user su where su.user_id=pp.CREATED_BY and su.DESCRIPTION=fe.name), (select hbme.employee_id from HLS_BP_MASTER_EMPLOYEE hbme where hbme.bp_id=pp.manufacturer_id and hbme.primary_flag='Y' and hbme.enabled_flag='Y'))) mobile, ( SELECT hbm.bp_name FROM hls_bp_master hbm WHERE hbm.bp_id = pp.seller_id ) seller_bp_name, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v. CODE = 'INSURANCE_PURCHASE_STATUS' AND v.code_value = pp.insurance_flag ) insurance_flag_n, pp.rent_plan_notice_flag, (SELECT v.meaning AS value_name FROM sys_code_value_b_v v WHERE v.CODE = 'SYS.YES_NO' and v.code_value=pp.rent_plan_notice_flag) rent_plan_notice_flag_n, pp.manufacturer_sign_type, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v.CODE = 'SIGN_METHOD' AND v.code_value = pp.manufacturer_sign_type) manufacturer_sign_type_n, pp.vender_sign_type, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v.CODE = 'SIGN_METHOD' AND v.code_value = pp.vender_sign_type) vender_sign_type_n, pp.dealer_sign_type, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v.CODE = 'SIGN_METHOD' AND v.code_value = pp.dealer_sign_type) dealer_sign_type_n, CC.created_by, M1.created_by AS tenant_created_by From CON_CONTRACT cc Left Join HLS_BP_MASTER m1 On cc.TENANT_ID = m1.BP_ID Left Join PRJ_PROJECT pp On pp.PROJECT_ID = cc.PROJECT_ID Left Join con_contract_change_req ccr On cc.CONTRACT_ID = ccr.CONTRACT_ID And ccr.status = 'APPROVED' And ccr.CHANGE_TYPE In ('PREPAYMENT', 'REPO')) t1
t1.contract_number like '%PRJ%'
and (exists( select 1 from fnd_org_unit fu, sys_user_allocation su,fnd_employee_assigns fa where su.user_id=#{createdBy} and su.EMPLOYEE_ASSIGN_ID=fa.EMPLOYEE_ASSIGN_ID and fa.unit_id =fu.unit_id and fu.unit_code != 'BUSINESS_DEPT_MANUFACTURER') OR exists( select 1 from fnd_employee a2,fnd_employee_assigns a3,FND_ORG_POSITION a4 where a3.employee_id=a2.employee_id and a4.position_id=a3.position_id and employee_code=#{request.employeeCode} AND A4.position_id IN(select b.position_id from sys_user_allocation a,fnd_employee_assigns b where a.employee_assign_id=b.employee_assign_id AND (a.user_id =T1.created_by or a.user_id=T1.tenant_created_by) )) )
