and t1.business_confirm_status =decode(#{createdStatus,jdbcType=CHAR},'Y','CREATED','N','UNCREATED')
or t1.business_confirm_status =decode(#{createdStatus,jdbcType=CHAR},'Y','CREATED','N','UNCREATED')
and t1.business_confirm_status =decode(#{createdStatus,jdbcType=CHAR},'Y','CREATED','N','UNCREATED')
and t1.dealer_biz_cfm_status =decode(#{dealerCreatedStatus,jdbcType=CHAR},'Y','CREATED','N','UNCREATED')
or t1.dealer_biz_cfm_status =decode(#{dealerCreatedStatus,jdbcType=CHAR},'Y','CREATED','N','UNCREATED')
and t1.dealer_biz_cfm_status =decode(#{dealerCreatedStatus,jdbcType=CHAR},'Y','CREATED','N','UNCREATED')
