select cc.CONTRACT_ID, cc.contract_number, cc.business_type, (SELECT hbt.description FROM hls_business_type hbt WHERE hbt.business_type = cc.business_type AND hbt.document_category = cc.document_category) business_type_n, cc.factory_id, (select hb.bp_name from hls_bp_master hb where hb.bp_id = cc.factory_id) factory_id_n, cc.bp_id_vender, (select hb.bp_name from hls_bp_master hb where hb.bp_id = cc.bp_id_vender) bp_id_vender_n, cc.tenant_id, (select hb.bp_name from hls_bp_master hb where hb.bp_id = cc.tenant_id) bp_id_tenant_n, cc.manufacturer_id from CON_CONTRACT cc where cc.contract_status in ('INCEPT','PENDING') and not exists (select 1 from hls_asset_class_line hac where hac.class_head_id = #{classHeadId} and hac.contract_id = cc.contract_id) and cc.manufacturer_id = #{bpId} and cc.lease_channel != 40
and cc.contract_number=#{contractNumber}
and cc.factory_id =#{factoryId}
and cc.bp_id_vender=#{vendor}
