select
/*提前结清款项*/ (nvl(v1.overdue_amount,0) + nvl(v1.outstanding_principal,0) + nvl(v1.period_interest,0) + nvl(v1.penalty_interest,0) + nvl(v1.nominal_price,0) )pre_amount,
v1.* from (select
/*期间利息*/ round( (nvl((v.outstanding_principal*v.int_rate/360*(to_number( trunc(#{dueDate}) - trunc(v.last_due_date) ))),0)) ,2) period_interest, /*期间批复利息*/ nvl((v.outstanding_principal*v.int_rate_reply_tmp/360*(to_number( trunc(#{dueDate}) - trunc(v.last_due_date) ))),0) period_reply_interest,
v.* from ( select
/*提前结清期数*/ ( select min(ccc.times) from con_contract_cashflow ccc where ccc.cf_item = 1 and ccc.contract_id = cc.contract_id and trunc(ccc.due_date) >=trunc(#{dueDate}) )times, /*逾期租金*/ (select nvl(sum(nvl(ccc.due_amount, 0) - nvl(ccc.received_amount, 0)), 0) from con_contract_cashflow ccc where ccc.contract_id = cc.contract_id and ccc.cf_item = 1 and ccc.write_off_flag != 'FULL' and trunc(ccc.due_date) < trunc(#{dueDate})) overdue_amount, /*剩余本金*/ nvl(( select nvl(ccc.outstanding_principal,0) from con_contract_cashflow ccc where ccc.contract_id = cc.contract_id and (ccc.cf_item = 1 or ccc.cf_item = 0) and trunc(ccc.due_date) < trunc(#{dueDate}) and ccc.times = ( select max(c.times) from con_contract_cashflow c where c.cf_item in (0,1) and c.contract_id = cc.contract_id and trunc(c.due_date) <trunc(#{dueDate}) ) and rownum = 1 ), 0)outstanding_principal, ( select case ccc.times when 0 then cc.inception_of_lease else ccc.due_date end from con_contract_cashflow ccc where ccc.contract_id = cc.contract_id and (ccc.cf_item = 1 or ccc.cf_item = 0) and trunc(ccc.due_date) < trunc(#{dueDate}) and ccc.times = ( select min(c.times)-1 from con_contract_cashflow c where c.cf_item = 1 and c.contract_id = cc.contract_id and trunc(c.due_date) >=trunc(#{dueDate}) ) and rownum = 1 )last_due_date, /*返利款金额*/ ( select nvl(sum(nvl(ccc.due_amount,0) - nvl(ccc.received_amount,0)),0) from con_contract_cashflow ccc where ccc.contract_id = cc.contract_id and ccc.cf_item = 60 and trunc(ccc.due_date) < trunc(#{dueDate}) )reply_amount, /*贴息金额*/ ( select nvl(sum(nvl(ccc.due_amount,0) - nvl(ccc.received_amount,0)),0) from con_contract_cashflow ccc where ccc.contract_id = cc.contract_id and ccc.cf_item = 61 and trunc(ccc.due_date) < trunc(#{dueDate}) )discount_amount, /*提前结清日所在区间天数*/ (((select trunc(ccc.due_date) from con_contract_cashflow ccc where ccc.contract_id = cc.contract_id and ccc.times = ( select min(ccc.times) from con_contract_cashflow ccc where ccc.cf_item = 1 and ccc.contract_id = cc.contract_id and trunc(ccc.due_date) >= trunc(#{dueDate})) and ccc.cf_item = 1 ))- ( select case ccc.times when 0 then cc.inception_of_lease else ccc.due_date end from con_contract_cashflow ccc where ccc.contract_id = cc.contract_id and (ccc.cf_item = 1 or ccc.cf_item = 0) and trunc(ccc.due_date) < trunc(#{dueDate}) and ccc.times = ( select min(c.times)-1 from con_contract_cashflow c where c.cf_item = 1 and c.contract_id = cc.contract_id and trunc(c.due_date) >= trunc(#{dueDate}) ) and rownum = 1 ))as days, /*结清前提前结清期数利息 */ (select ccc.interest from con_contract_cashflow ccc where ccc.contract_id = cc.contract_id and ccc.times = ( select min(ccc.times) from con_contract_cashflow ccc where ccc.cf_item = 1 and ccc.contract_id = cc.contract_id and trunc(ccc.due_date) >= trunc(#{dueDate})) and ccc.cf_item = 1) as interest,
cc.contract_id, cc.int_rate, (select pq.irr from prj_quotation pq where pq.source_document_id = cc.contract_id and pq.data_class = 'CON_QUOTATION' and pq.enabled_flag = 'Y' and rownum = 1) irr, (select pq.int_rate_reply from prj_quotation pq where pq.source_document_id = cc.contract_id and pq.data_class = 'CON_QUOTATION' and pq.enabled_flag = 'Y' and rownum = 1) int_rate_reply_tmp, /*保证金*/ /*nvl((select (nvl(sum(t.transaction_amount),0) - nvl(sum(t.WRITE_OFF_AMOUNT), 0) - nvl(sum(t.BLOCK_AMOUNT), 0)) FROM csh_transaction t WHERE t.contract_id = cc.contract_id AND t.transaction_type = 'DEPOSIT' AND t.reversed_flag = 'N' AND NOT EXISTS (SELECT 1 FROM csh_deposit_deduct_req_hd cddrh WHERE cddrh.transaction_id = t.transaction_id AND cddrh.req_status IN ('NEW', 'REJECTED', 'APPROVING'))),0)*/ (select nvl(sum(nvl(ccc.due_amount,0) - nvl(ccc.received_amount,0) ),0) from con_contract_cashflow ccc where ccc.contract_id = cc.contract_id and ccc.cf_item = 51) deposit, /*罚息金额*/ nvl((select sum(nvl(ccc.due_amount, 0) - nvl(ccc.received_amount, 0)) from con_contract_cashflow ccc where ccc.contract_id = cc.contract_id and ccc.cf_item = 9), 0) penalty_interest, /*名义货价*/ (select nvl(sum(nvl(ccc.due_amount,0) - nvl(ccc.received_amount,0) ),0) from con_contract_cashflow ccc where ccc.contract_id = cc.contract_id and ccc.cf_item = 8) nominal_price, cc.division, pp.manufacturer_id, cccr.status from con_contract cc,con_contract_change_req cccr,prj_project pp where cc.contract_id = cccr.contract_id and cc.contract_number = pp.project_number and cccr.change_req_id = #{changeReqId} )v) v1

SELECT cc.contract_id, cc.contract_status, cc.contract_number, quo.INT_RATE_IMPLICIT as int_rate_reply,quo.FLOATING_WAY_RATE as int_rate_float_rate,
nvl2( quo.grace_month_one, quo.grace_month_one || '-', '' ) || nvl2( quo.grace_month_two, quo.grace_month_two || '-', '' ) || nvl2( quo.grace_month_three, '' || quo.grace_month_three, '' ) grace_month, nvl( ( SELECT '是' FROM dual WHERE EXISTS ( SELECT 1 FROM con_contract_cashflow ccc WHERE ccc.contract_id = cc.contract_id AND cc.contract_status != 'SIGN' AND cc.contract_status != 'CANCEL' AND ccc.cf_item IN ( 1, 11, 13, 9, 99 ) AND ( EXISTS ( SELECT 1 FROM dual WHERE
nvl( ccc.due_amount, 0 ) > nvl( ccc.received_amount, 0 ) AND trunc( ccc.due_date ) < trunc( SYSDATE ) )
) ) ), '否' ) current_overdue_status,
nvl( ( SELECT '是' FROM dual WHERE EXISTS ( SELECT 1 FROM con_contract_cashflow ccc WHERE ccc.contract_id = cc.contract_id AND cc.contract_status != 'SIGN' AND cc.contract_status != 'CANCEL' AND ccc.cf_item IN ( 1, 11, 13, 9, 99 ) AND ( EXISTS ( SELECT 1 FROM dual WHERE nvl( ccc.due_amount, 0 ) = nvl( ccc.received_amount, 0 ) AND trunc( ccc.due_date ) < ( SELECT trunc( max( tra.transaction_date ) ) FROM csh_transaction tra, csh_write_off cwo WHERE cwo.csh_transaction_id = tra.transaction_id AND cwo.cashflow_id = ccc.cashflow_id ) ) ) ) ), '否' ) history_overdue_status,
( SELECT
nvl( ( SELECT sum( nvl( ccc.due_amount, 0 ) - nvl( ccc.received_amount, 0 ) ) FROM con_contract_cashflow ccc WHERE ccc.contract_id = cc.contract_id AND ccc.cf_item IN ( 1, 11, 13, 9, 99 ) AND trunc( ccc.due_date ) < trunc( SYSDATE ) ), 0 )
FROM dual ) current_overdue_amount,
CASE
WHEN pp.DIVISION = 'ENGINEERING_MACHINERY' THEN (SELECT to_char(substr(wm_concat(to_char(ppli.full_name || '-' || (select ic.attribute_value from yx_lease_item_classify ic where ic.classify_id = ppli.CLASSIFY_ID) || '-' || ppli.serial_number)), 0, 2000)) FROM prj_project_lease_item ppli WHERE ppli.project_id = pp.project_id) WHEN ( pp.DIVISION = 'COMMERCIAL_VEHICLE') THEN (SELECT to_char(substr(wm_concat(to_char(ppli.BRAND_C || '-' || ppli.SERIES_C || '-' || ppli.MODEL_C)), 0, 2000)) FROM prj_project_lease_item ppli WHERE ppli.project_id = pp.project_id)
END item_info,
case when (select count(1) from con_contract_cashflow ccc where ccc.write_off_flag='NOT' and cc.contract_id=ccc.contract_id)>0 then '未核销' when (select count(1) from con_contract_cashflow ccc where ccc.write_off_flag='PARTIAL' and cc.contract_id=ccc.contract_id)>0 then '部分核销' when (select count(1) from con_contract_cashflow ccc where ccc.write_off_flag='FULL' and cc.contract_id=ccc.contract_id)>0 then '完全核销' end as pre_payments_status, (SELECT v.meaning AS value_name FROM sys_code_value_b_v v WHERE v.code = 'PRJ_EQUIPMENT_TYPE' and v.code_value=pp.second_hand_flag) second_hand_flag_n, (SELECT v.meaning AS value_name FROM sys_code_value_b_v v WHERE v.CODE = 'PAYMENT_BP_TYPE' and v.code_value = cc.payment_bp_type) internal_bp_n,
( SELECT hlc.description FROM hls_lease_channel hlc WHERE hlc.enabled_flag = 'Y' AND hlc.lease_channel = cc.lease_channel ) lease_channel_n, ( SELECT hbt.description FROM hls_business_type hbt WHERE hbt.document_category = 'CONTRACT' AND hbt.business_type NOT IN ( 'CREDIT_LINE' ) AND hbt.business_type = cc.business_type ) business_type_n, ( SELECT fe.name FROM fnd_employee fe WHERE fe.employee_id = cc.employee_id ) employee_name, ( SELECT hbm.bp_name FROM hls_bp_master hbm WHERE hbm.bp_id = cc.manufacturer_id ) manufacturer_bp_name, ( SELECT hbmf.bp_name FROM hls_bp_master hbmf WHERE hbmf.bp_id = cc.factory_id ) factory_bp_name, ( SELECT hbmv.bp_name FROM hls_bp_master hbmv WHERE hbmv.bp_id = cc.bp_id_vender ) vender_bp_name, ( SELECT hbm.bp_name FROM hls_bp_master hbm WHERE hbm.bp_id = pp.seller_id ) seller_bp_name, hbmt.bp_name tenant_bp_name, ( SELECT hbt.description FROM hls_business_type hbt WHERE hbt.document_category = 'HLS_BP_MASTER' AND hbt.business_type = hbmt.bp_class ) bp_class_n, ( SELECT t.description FROM hls_stat_class t WHERE class_usage = 'BIZ_PARTNER' AND enabled_flag = 'Y' AND t.class_id = hbmt.ECONOMIC_INDU_CLASSIFY ) industry_n,
(select sc.meaning value_name from sys_code_value_b_v sc where sc.code = 'FND.ENTERPRISE_SCALE_TYPE' and sc.code_value = hbmt.enterprise_scale) enterprise_scale, hbmt.legal_person, ( SELECT fp.description FROM hls_bp_master_address hbma, fnd_province fp WHERE hbma.bp_id = hbmt.bp_id AND hbma.address_type = 'COMPANY_ADDRESS' AND ROWNUM = 1 AND fp.province = hbma.province_id ) province_name, ( SELECT fc.description FROM hls_bp_master_address hbma, fnd_city fc WHERE hbma.bp_id = hbmt.bp_id AND hbma.address_type = 'COMPANY_ADDRESS' AND ROWNUM = 1 AND fc.city = hbma.city_id ) city_name, CASE hbmt.bp_class WHEN 'NP' THEN ( SELECT hbma.address FROM hls_bp_master_address hbma WHERE hbma.bp_id = hbmt.bp_id AND hbma.address_type = 'ID_ADDRESS' AND ROWNUM = 1 ) WHEN 'ORG' THEN ( SELECT hbma.address FROM hls_bp_master_address hbma WHERE hbma.bp_id = hbmt.bp_id AND hbma.address_type = 'REGISTRATION_ADDRESS' AND ROWNUM = 1 ) END address, ( SELECT hbma.address FROM hls_bp_master_address hbma WHERE hbma.bp_id = hbmt.bp_id AND hbma.address_type = 'HOUSE_ADDRESS' AND ROWNUM = 1 ) current_address, CASE hbmt.bp_class WHEN 'NP' THEN hbmt.id_card_no WHEN 'ORG' THEN hbmt.regno END card_num, CASE hbmt.bp_class WHEN 'NP' THEN hbmt.PHONE ELSE ( SELECT hbma.phone FROM hls_bp_master_address hbma WHERE hbma.bp_id = hbmt.bp_id AND ROWNUM = 1 ) END lp_cell_phone, to_char( pp.creation_date, 'YYYY-MM-DD' ) prj_creation_date, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v.CODE = 'PRJ501_PRJ_STATUS' AND v.code_value = pp.project_status ) project_status_n, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v.CODE = 'SIGN_STATUS' AND v.code_value = pp.sign_status ) sign_status_n, ( SELECT v.meaning FROM csh_payment_req_ln cprl, csh_payment_req_hd cprh, con_contract_cashflow ccc, sys_code_value_b_v v WHERE cprh.payment_req_id = cprl.payment_req_id AND cprl.source_doc_line_id = ccc.cashflow_id AND ccc.contract_id = cc.contract_id AND ccc.cf_item = 0 AND ccc.times = 0 AND v.code = 'HLS_WFL_STATUS' AND v.code_value = cprh.payment_req_status AND ROWNUM = 1 ) payment_req_status_n, to_char(cc.lease_start_date,'YYYY-MM-DD') lease_start_date_n, to_char(cc.inception_of_lease,'YYYY-MM-DD') inception_of_lease_n, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v.code = 'CON.CONTRACT_STATUS' AND v.code_value = cc.contract_status ) contract_status_n, ( SELECT hpd.definition_name FROM hls_product_definition hpd WHERE hpd.definition_id = quo.plan_id ) definition_name, ( SELECT hpl.description FROM hls_price_list hpl WHERE hpl.price_list = quo.price_list ) price_list_n,
quo.lease_term_m lease_term,
quo.base_rate,
( SELECT count( 1 ) FROM prj_project_lease_item ppli WHERE ppli.project_id = pp.project_id ) item_num, ( SELECT sum( ppli.price ) FROM prj_project_lease_item ppli WHERE ppli.project_id = pp.project_id ) item_amount, quo.down_payment, quo.down_payment_ratio, quo.finance_amount, ( SELECT sum( ccc.due_amount ) FROM con_contract_cashflow ccc WHERE ccc.contract_id = cc.contract_id AND ccc.cf_type = 1 ) lease_sum_amount, quo.deposit_ratio, quo.deposit,
nvl( ( SELECT ccc.due_amount FROM con_contract_cashflow ccc WHERE ccc.contract_id = cc.contract_id AND ccc.cf_item = 66 ), 0 ) discount_amount, quo.lease_charge_ratio, quo.lease_charge, nvl( quo.lease_charge, 0 ) + nvl( ( SELECT ccc.due_amount FROM con_contract_cashflow ccc WHERE ccc.contract_id = cc.contract_id AND ccc.cf_item = 66 ), 0 ) receive_lease_charge, quo.residual_value, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v.code = 'GRACE_TYPE' AND v.code_value = quo.grace_type ) grace_type_n,
quo.irr, to_char( cc.lease_end_date, 'YYYY-MM-DD' ) lease_end_date_n, ( SELECT sum( nvl( ccc.due_amount, 0 ) - nvl( ccc.received_amount, 0 ) ) FROM con_contract_cashflow ccc WHERE ccc.contract_id = cc.contract_id AND ccc.cf_type = 1 ) remaining_rent, ( SELECT sum( nvl( ccc.principal, 0 ) - nvl( ccc.received_principal, 0 ) ) FROM con_contract_cashflow ccc WHERE ccc.contract_id = cc.contract_id AND ccc.cf_type = 1 ) remaining_principal, nvl( round( ( SELECT sum( nvl( csh.transaction_amount, 0 ) ) - sum( nvl( csh.write_off_amount, 0 ) ) FROM csh_transaction csh WHERE csh.contract_id = cc.contract_id AND csh.business_type = 'DEPOSIT' AND csh.reversed_flag = 'N' ), 2 ), 0 ) remaining_margin, CASE WHEN cc.CONTRACT_STATUS IN ( 'INCEPT', 'PENDING' ) THEN CASE WHEN ( round( ( SELECT sum( nvl( ccc.principal, 0 ) - nvl( ccc.received_principal, 0 ) ) FROM con_contract_cashflow ccc WHERE ccc.contract_id = cc.contract_id AND ccc.cf_type = 1 ), 2 ) - nvl( round( ( SELECT sum( nvl( csh.transaction_amount, 0 ) ) - sum( nvl( csh.write_off_amount, 0 ) ) FROM csh_transaction csh WHERE csh.contract_id = cc.contract_id AND csh.business_type = 'DEPOSIT' ), 2 ), 0 ) ) <0 THEN 0 ELSE ( round( ( SELECT sum( nvl( ccc.principal, 0 ) - nvl( ccc.received_principal, 0 ) ) FROM con_contract_cashflow ccc WHERE ccc.contract_id = cc.contract_id AND ccc.cf_type = 1 ), 2 ) - nvl( round( ( SELECT sum( nvl( csh.transaction_amount, 0 ) ) - sum( nvl( csh.write_off_amount, 0 ) ) FROM csh_transaction csh WHERE csh.contract_id = cc.contract_id AND csh.business_type = 'DEPOSIT' ), 2 ), 0 ) ) END ELSE NULL END remaining_exposure, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v.code = 'SYS.YES_NO' AND v.code_value = quo.repay_flag ) repay_flag_n, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v.code = 'SYS.YES_NO' AND v.code_value = pp.insurance_flag ) insurance_flag_n,
nvl( ( SELECT '是' FROM dual WHERE pp.tenant_id = pp.bp_id_vender ), '否' ) tenant_dealer_flag,
( SELECT hrp.reply_product_code FROM hls_product_definition hpd, hls_reply_product hrp WHERE hpd.definition_id = quo.plan_id AND hpd.reply_product_id = hrp.reply_product_id ) reply_product_code, ( SELECT scv.meaning FROM hls_asset_class_head head, hls_asset_class_line line, sys_code_b scb, sys_code_value_b scv WHERE head.class_head_id = line.class_head_id AND scb.CODE = 'ASSET_CLASS' AND scb.CODE_ID = scv.CODE_ID AND scv.value = line.REVIEW_LEVEL AND head.approve_time = ( SELECT max( head.approve_time ) FROM hls_asset_class_head head, hls_asset_class_line line WHERE head.class_head_id = line.class_head_id AND head.approve_status = 'APPROVED' AND line.contract_id = cc.contract_id ) AND line.contract_id = cc.contract_id ) review_level_n, quo.int_rate, pp.division, ( SELECT hd.description FROM hls_division hd WHERE hd.division = pp.division ) division_n, nvl( ( SELECT sum( nvl( ccc.due_amount, 0 ) ) FROM con_contract_cashflow ccc WHERE ccc.contract_id = cc.contract_id AND ccc.cf_item = 61 ), 0 ) discount_rental, ( nvl( ( SELECT sum( nvl( ccc.due_amount, 0 ) ) FROM con_contract_cashflow ccc WHERE ccc.contract_id = cc.contract_id AND ccc.cf_item = 61 ), 0 ) + nvl( ( SELECT ccc.due_amount FROM con_contract_cashflow ccc WHERE ccc.contract_id = cc.contract_id AND ccc.cf_item = 66 ), 0 ) ) contract_discount, nvl( ( SELECT sum( nvl( ccc.due_amount, 0 ) ) FROM con_contract_cashflow ccc WHERE ccc.contract_id = cc.contract_id AND ccc.cf_item = 67 ), 0 ) BACK_LEASE_CHARGE, nvl( ( SELECT sum( nvl( ccc.due_amount, 0 ) ) FROM con_contract_cashflow ccc WHERE ccc.contract_id = cc.contract_id AND ccc.cf_item = 60 ), 0 ) BACK_RENTAL, ( nvl( ( SELECT sum( nvl( ccc.due_amount, 0 ) ) FROM con_contract_cashflow ccc WHERE ccc.contract_id = cc.contract_id AND ccc.cf_item = 67 ), 0 ) + nvl( ( SELECT sum( nvl( ccc.due_amount, 0 ) ) FROM con_contract_cashflow ccc WHERE ccc.contract_id = cc.contract_id AND ccc.cf_item = 60 ), 0 ) ) CONTRACT_BACK, (select scvb.meaning from sys_code_b scb, sys_code_value_b scvb where scb.code = 'SIGN_METHOD' and scb.code_id = scvb.code_id and scvb.value = cc.sign_type) sign_type_n, cc.sign_type, (select cccr.CHANGE_TYPE from CON_CONTRACT_CHANGE_REQ cccr where cc.CONTRACT_ID = cccr.CONTRACT_ID and cccr.status = 'APPROVED' and cccr.CHANGE_TYPE IN ('PREPAYMENT', 'REPO')) CHANGE_TYPE, (select meaning from CON_CONTRACT_CHANGE_REQ cccr, sys_code_value_b_v sc where cc.CONTRACT_ID = cccr.CONTRACT_ID and cccr.status = 'APPROVED' and cccr.CHANGE_TYPE IN ('PREPAYMENT', 'REPO') and sc.code = 'CON.CONTRACT_CHANGE_TYPE' and sc.code_value = cccr.change_type) CHANGE_TYPE_N, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v.code = 'EXEMPT_PENALTY_INT' AND v.code_value = quo.grace_flag)grace_flag_n, quo.grace_period, nvl((select sum(nvl(ccc.due_amount,0) - nvl(ccc.received_amount,0)) from con_contract_cashflow ccc where ccc.contract_id = cc.contract_id and ccc.cf_type = 1 and trunc(ccc.due_date) >= trunc(sysdate)),0) due_amount_current, cc.project_id
FROM con_contract cc, hls_bp_master hbmt, prj_project pp, prj_quotation quo WHERE cc.tenant_id = hbmt.bp_id AND cc.project_id = pp.project_id AND quo.source_document_category = 'PRJ_PROJECT' AND quo.source_document_id = pp.project_id and cc.contract_number like '%PRJ%'
and (exists( select 1 from fnd_org_unit fu, sys_user_allocation su,fnd_employee_assigns fa where su.user_id=#{createdBy} and su.EMPLOYEE_ASSIGN_ID=fa.EMPLOYEE_ASSIGN_ID and fa.unit_id =fu.unit_id and fu.unit_code != 'BUSINESS_DEPT_MANUFACTURER') OR exists( select 1 from fnd_employee a2,fnd_employee_assigns a3,FND_ORG_POSITION a4 where a3.employee_id=a2.employee_id and a4.position_id=a3.position_id and employee_code=#{request.employeeCode} AND A4.position_id IN(select b.position_id from sys_user_allocation a,fnd_employee_assigns b where a.employee_assign_id=b.employee_assign_id AND (a.user_id =pp.created_by or a.user_id=hbmt.created_by) )) )
and pp.division = #{divisionN}
and nvl((select sum(nvl(ccc.due_amount,0) - nvl(ccc.received_amount,0)) from con_contract_cashflow ccc where ccc.contract_id = cc.contract_id and ccc.cf_type = 1 and trunc(ccc.due_date) >= trunc(sysdate)),0) >= #{due_amount_current_from}
and nvl((select sum(nvl(ccc.due_amount,0) - nvl(ccc.received_amount,0)) from con_contract_cashflow ccc where ccc.contract_id = cc.contract_id and ccc.cf_type = 1 and trunc(ccc.due_date) >= trunc(sysdate)),0) <= #{due_amount_current_to}
and exists (select 1 from sys_user su, hls_bp_master_role hbmr where su.bp_id = hbmr.bp_id and (su.user_id = #{user_id} or su.user_id in (select su1.user_id from sys_user su1,sys_user su2,hls_bp_master_relation hmr1 where su2.user_id = #{user_id} and su1.bp_id = hmr1.bp_id and hmr1.relation_type = 'PARENT_COMPANY' and hmr1.related_bp_id = su2.bp_id) or su.user_id in (select su1.user_id from sys_user su1,sys_user su2,hls_bp_master_relation hmr1 where su2.user_id = #{user_id} and su1.bp_id = hmr1.related_bp_id and hmr1.relation_type = 'SUBSIDIARY' and hmr1.bp_id = su2.bp_id)) and (exists (select 1 from hls_bp_master_relation rel where hbmr.bp_category = 'MANAGEMENT_COMPANY' and rel.bp_id = su.bp_id and rel.relation_type = 'MANUFACTURER' and cc.manufacturer_id = rel.related_bp_id) or exists (select 1 from dual where hbmr.bp_category = 'MANUFACTURER' and cc.manufacturer_id = su.bp_id) or exists (select 1 from dual where hbmr.bp_category = 'VENDER' and cc.factory_id = su.bp_id) or exists (select 1 from dual where hbmr.bp_category = 'DEALER' and cc.bp_id_vender = su.bp_id)))
and cc.contract_number like #{contractNumber}
and (select hlc.description from hls_lease_channel hlc where hlc.enabled_flag = 'Y' and hlc.lease_channel = cc.lease_channel) = #{leaseChannelN}
and (SELECT hbt.description FROM hls_business_type hbt WHERE hbt.document_category = 'CONTRACT' AND hbt.business_type NOT IN ('CREDIT_LINE') and hbt.business_type = cc.business_type) = #{businessTypeN}
and (select fe.name from fnd_employee fe where fe.employee_id = cc.employee_id) like #{employeeName}
and (select hbm.bp_name from hls_bp_master hbm where hbm.bp_id = cc.manufacturer_id) = #{manufacturerBpNameN}
and hbmt.bp_name like #{tenantBpName}
and (select v.meaning from sys_code_value_b_v v where v.code = 'SYS.YES_NO' and v.code_value = cc.vender_mode_flag) = #{vender_mode_flag_n}
and (select v.meaning from sys_code_value_b_v v where v.code = 'PRJ_EQUIPMENT_TYPE' and v.code_value = pp.second_hand_flag) = #{secondHandFlagN}
and (SELECT v.meaning FROM sys_code_value_b_v v WHERE v. CODE = 'PRJ501_PRJ_STATUS' AND v.code_value = pp.project_status) = #{projectStatusN}
and (SELECT v.meaning FROM sys_code_value_b_v v WHERE v. CODE = 'SIGN_STATUS' AND v.code_value = pp.sign_status) = #{signStatusN}
and yx_hls_bp_master_pkg.get_contract_rece(cc.contract_id) = #{pre_payments_status_n}
and (SELECT v.meaning FROM csh_payment_req_ln cprl, csh_payment_req_hd cprh, con_contract_cashflow ccc, sys_code_value_b_v v WHERE cprh.payment_req_id = cprl.payment_req_id AND cprl.source_doc_line_id = ccc.cashflow_id AND ccc.contract_id = cc.contract_id AND ccc.cf_item = 0 AND ccc.times = 0 AND v.code = 'HLS_WFL_STATUS' AND v.code_value = cprh.payment_req_status AND rownum = 1) = #{paymentReqStatusN}
and (SELECT v.meaning FROM sys_code_value_b_v v WHERE v.code = 'CON.CONTRACT_STATUS' AND v.code_value = cc.contract_status) = #{contractStatusN}
and nvl((select '是' from dual where exists (select 1 from con_contract_cashflow ccc where ccc.contract_id = cc.contract_id and cc.contract_status != 'SIGN' and cc.contract_status != 'CANCEL' and ccc.cf_item in (1, 11, 13, 9, 99) and exists (select 1 from dual where (cc.lease_channel = '10' or (cc.lease_channel = '20' and cc.substitute_receipt_flag != 'Y')) and nvl(ccc.due_amount, 0) > nvl(ccc.received_amount, 0) and trunc(ccc.due_date) < trunc(sysdate)))), '否') = #{currentOverdueStatus}
and nvl((select '是' from dual where exists (select 1 from con_contract_cashflow ccc where ccc.contract_id = cc.contract_id and cc.contract_status != 'SIGN' and cc.contract_status != 'CANCEL' and ccc.cf_item in (1, 11, 13, 9, 99) and exists (select 1 from dual where (cc.lease_channel = '10' or (cc.lease_channel = '20' and cc.substitute_receipt_flag != 'Y')) and nvl(ccc.due_amount, 0) = nvl(ccc.received_amount, 0) and trunc(ccc.due_date) < (select trunc(max(tra.transaction_date)) from csh_transaction tra, csh_write_off cwo where cwo.csh_transaction_id = tra.transaction_id and cwo.cashflow_id = ccc.cashflow_id)))), '否') = #{historyOverdueStatus}
and cc.lease_start_date >= to_date(#{leaseStartDateFrom},'YYYY-MM-DD')
and cc.lease_start_date <= to_date(#{leaseStartDateTo},'YYYY-MM-DD')
and pp.creation_date <= to_date(#{prjCreatTo},'YYYY-MM-DD')
and pp.creation_date >= to_date(#{prjCreatFrom},'YYYY-MM-DD')
and (select hbmf.bp_name from hls_bp_master hbmf where hbmf.bp_id = cc.factory_id) = #{factoryBpNameN,jdbcType=VARCHAR}
and cc.bp_id_vender = #{bpIdVender}
and (select line.review_level from hls_asset_class_head head, hls_asset_class_line line where head.class_head_id = line.class_head_id and head.approve_time = (select max(head.approve_time) from hls_asset_class_head head, hls_asset_class_line line where head.class_head_id = line.class_head_id and head.approve_status = 'APPROVED' and line.contract_id = cc.contract_id) and line.contract_id = cc.contract_id) = #{reviewLevel}
and cc.sign_type = #{signType}
and (select cccr.CHANGE_TYPE from CON_CONTRACT_CHANGE_REQ cccr where cc.CONTRACT_ID = cccr.CONTRACT_ID and cccr.status = 'APPROVED' and cccr.CHANGE_TYPE IN ('PREPAYMENT', 'REPO')) = #{changeType}
and ( SELECT hbmv.bp_name FROM hls_bp_master hbmv WHERE hbmv.bp_id = cc.bp_id_vender ) like #{venderBpName}
and cc.partners_contract_number like concat('%',concat(#{partners_contract_number},'%'))
and cc.partners_payment_number like concat('%',concat(#{partners_payment_number},'%'))

select hbrp.DEFAULT_VALUE
from CON_CONTRACT cc,
     hls_product_definition hbmr,
     hls_product_definition_para hbrp
where cc.CONTRACT_ID = #{contractId}
  and cc.project_id = hbmr.reply_product_id
  and hbrp.definition_id = hbmr.definition_id
  and hbrp.product_PARA = #{replyPara}

Select t1.* From (Select cc.PROJECT_ID, cc.CONTRACT_ID, cc.CONTRACT_NUMBER, cc.TENANT_ID, (Select hbt.DESCRIPTION From HLS_BUSINESS_TYPE hbt Where hbt.BUSINESS_TYPE = cc.BUSINESS_TYPE And hbt.DOCUMENT_CATEGORY = cc.DOCUMENT_CATEGORY) As BUSINESS_TYPE_N, cc.BUSINESS_TYPE, (Select hdc.DESCRIPTION From HLS_DOCUMENT_CATEGORY hdc Where hdc.DOCUMENT_CATEGORY = cc.DOCUMENT_CATEGORY And hdc.DOCUMENT_CATEGORY = cc.DOCUMENT_CATEGORY) As DOCUMENT_CATEGORY_N, (SELECT v.description FROM hls_document_type v WHERE V.enabled_flag = 'Y' AND v.document_category = 'CON_CONTRACT' and v.document_type in ('CONL', 'CONLB') AND v.document_type = CC.document_type) document_type_n, (Select v.meaning From sys_code_value_b_v v Where v.CODE = 'CON.FLOATING_RANGE_METHOD' And v.code_value = cc.floating_range_method) floating_range_method_n,
(Select v.meaning From sys_code_value_b_v v Where v.CODE = 'FND.BASE_RATE_TYPE' And v.code_value = cc.base_rate_type) base_rate_type_n, m1.BP_NAME As BP_ID_TENANT_N, m1.BP_CODE, (Select hbt.DESCRIPTION From HLS_BUSINESS_TYPE hbt Where hbt.BUSINESS_TYPE = m1.BP_CLASS And hbt.DOCUMENT_CATEGORY = 'HLS_BP_MASTER') As bp_class_n, cc.bp_id_vender, (Select hb.bp_name From hls_bp_master hb Where hb.bp_id = cc.bp_id_vender) bp_id_vender_n, cc.FACTORY_ID, (Select hb.bp_name From hls_bp_master hb Where hb.bp_id = cc.factory_id) As factory_id_n, cc.LEASE_CHANNEL, (Select t1.description From hls_lease_channel t1 Where t1.lease_channel = cc.lease_channel) As lease_channel_n, cc.manufacturer_id, (Select hb.bp_code From hls_bp_master hb Where hb.bp_id = cc.manufacturer_id) manufacturer_code, (Select hb.bp_name From hls_bp_master hb Where hb.bp_id = cc.manufacturer_id) manufacturer_id_n, (Select hd.description From hls_division hd Where hd.division = cc.DIVISION) division_n, cc.DIVISION, cc.LEASE_START_DATE inception_of_lease, to_char((Select pp.lease_start_date From prj_project pp Where pp.project_id = cc.project_id),'yyyy-mm-dd') prj_lease_start_date, cc.FLOATING_RANGE_METHOD, cc.BASE_RATE_TYPE, cc.CURRENCY, cc.ANNUAL_PAY_TIMES, cc.BILLING_METHOD, cc.CONTRACT_NAME, (Select v.meaning From sys_code_value_b_v v Where v.CODE = 'HLS500_ANNUAL_PAY_TIMES' And v.code_value = to_char(cc.annual_pay_times)) annual_pay_times_n, cc.FINANCE_AMOUNT, cc.INT_RATE, cc.LEASE_TERM, cc.LEASE_TIMES, cc.PENALTY_RATE, pp.PROJECT_NUMBER, cc.EMPLOYEE_ID, (Select fe.NAME From fnd_employee fe Where fe.EMPLOYEE_ID = cc.EMPLOYEE_ID) employee_id_n, cc.CONTRACT_STATUS, (SELECT v.MEANING FROM sys_code_value_b_v v WHERE v.code = 'CON.CONTRACT_STATUS' AND V.code_value = cc.CONTRACT_STATUS) AS CONTRACT_STATUS_N, cc.creation_date, cc.pledge_flag, (Select v.meaning From sys_code_value_b_v v Where v.CODE = 'SYS.YES_NO' And v.code_value = cc.pledge_flag) pledge_flag_n, cc.TERMINATION_DATE, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v.code = 'SIGN_METHOD' AND v.code_value= cc.sign_type) sign_type_n, cc.sign_type, pp.partners_contract_status, (select sv.MEANING from sys_code_value_b_v sv where sv.CODE = 'SY_CONTRACT_STATUS' and sv.code_value = pp.partners_contract_status) partners_contract_status_n, (SELECT v.meaning AS value_name FROM sys_code_value_b_v v WHERE v.code = 'PRJ_EQUIPMENT_TYPE' and v.code_value=cc.second_hand_flag) second_hand_flag_n, cc.payment_bp_type, (SELECT v.meaning AS value_name FROM sys_code_value_b_v v WHERE v.CODE = 'PAYMENT_BP_TYPE' and v.code_value = cc.payment_bp_type) payment_bp_type_n, cc.PAYMENT_BP_ID, (SELECT m.bp_name FROM hls_bp_master m WHERE m.bp_id = cc.PAYMENT_BP_ID) AS PAYMENT_BP_ID_N, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v. CODE = 'INSURANCE_PURCHASE_STATUS' AND v.code_value = pp.insurance_flag) insurance_flag_n, pp.rent_plan_notice_flag, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v.CODE = 'SYS.YES_NO' and v.code_value=pp.rent_plan_notice_flag) rent_plan_notice_flag_n, pp.manufacturer_sign_type, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v.CODE = 'SIGN_METHOD' AND v.code_value = pp.manufacturer_sign_type) manufacturer_sign_type_n, pp.vender_sign_type, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v.CODE = 'SIGN_METHOD' AND v.code_value = pp.vender_sign_type) vender_sign_type_n, pp.dealer_sign_type, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v.CODE = 'SIGN_METHOD' AND v.code_value = pp.dealer_sign_type) dealer_sign_type_n, (SELECT fe.mobile FROM fnd_employee fe WHERE fe.employee_id = (SELECT fe.employee_id FROM FND_EMPLOYEE_ASSIGNS fe, SYS_USER_ALLOCATION a WHERE fe.EMPLOYEE_ASSIGN_ID=a.EMPLOYEE_ASSIGN_ID and a.user_id = pp.CREATED_BY )) mobile, CC.created_by, M1.created_by AS tenant_created_by From CON_CONTRACT cc Left Join HLS_BP_MASTER m1 On cc.TENANT_ID = m1.BP_ID Left Join PRJ_PROJECT pp On pp.PROJECT_ID = cc.PROJECT_ID where cc.document_type in ('CONL', 'CONLB') and cc.data_class='NORMAL' AND CC.CONTRACT_STATUS IN('INCEPT','PENDING') ) t1
and (exists( select 1 from fnd_org_unit fu, sys_user_allocation su,fnd_employee_assigns fa where su.user_id=#{createdBy} and su.EMPLOYEE_ASSIGN_ID=fa.EMPLOYEE_ASSIGN_ID and fa.unit_id =fu.unit_id and fu.unit_code != 'BUSINESS_DEPT_MANUFACTURER') OR exists( select 1 from fnd_employee a2,fnd_employee_assigns a3,FND_ORG_POSITION a4 where a3.employee_id=a2.employee_id and a4.position_id=a3.position_id and employee_code=#{request.employeeCode} AND A4.position_id IN(select b.position_id from sys_user_allocation a,fnd_employee_assigns b where a.employee_assign_id=b.employee_assign_id AND (a.user_id =T1.created_by or a.user_id=T1.tenant_created_by) )) )
and t1.division = #{division}
and t1.partners_contract_number like concat('%',concat(#{partnersContractNumber},'%'))
and t1.partners_payment_number like concat('%',concat(#{partnersPaymentNumber},'%'))
and t1.CONTRACT_NUMBER like #{contractNumber}
and t1.BP_ID_TENANT_N like #{bpIdTenantN}
and t1.FACTORY_ID = #{factoryId}
and t1.FINANCE_AMOUNT >= #{financeAmountFrom}
and t1.FINANCE_AMOUNT <= #{financeAmountTo}
and t1.LEASE_CHANNEL = #{leaseChannel}
and t1.EMPLOYEE_ID = #{employeeId}
and t1.CONTRACT_STATUS = #{contractStatus}
and t1.INCEPTION_OF_LEASE >= to_date(#{inceptionOfLeaseFrom},'yyyy-MM-dd')
and t1.INCEPTION_OF_LEASE <= to_date(#{inceptionOfLeaseTo},'yyyy-MM-dd')
and t1.DUE_DATE >= to_date(#{dueDateFrom},'yyyy-MM-dd')
and t1.DUE_DATE < to_date(#{dueDateTo},'yyyy-MM-dd')+1
and t1.TERMINATION_DATE >= to_date(#{terminationDateFrom},'yyyy-MM-dd')
and t1.TERMINATION_DATE < to_date(#{terminationDateTo},'yyyy-MM-dd')+1
and t1.LEASE_TERM >= #{leaseTermFrom}
and t1.LEASE_TERM <= #{leaseTermTo}
and t1.second_hand_flag = #{secondHandFlag}
and t1.contract_id = #{contractId}
and t1.manufacturer_id = #{manufacturerId}
and t1.business_type = #{businessType}
and nvl((select min(cwo.write_off_date) from csh_write_off cwo where cwo.cf_item = 0 and cwo.contract_id = t1.contract_id), (select t1.lease_start_date from dual where to_char(t1.creation_date,'YYYY-MM-DD') = '2019-10-01' and t1.contract_status in ('PENDING', 'INCEPT', 'TERMINATE'))) >= to_date(#{leaseStartDateFrom},'yyyy-MM-dd')
and nvl((select min(cwo.write_off_date) from csh_write_off cwo where cwo.cf_item = 0 and cwo.contract_id = t1.contract_id), (select t1.lease_start_date from dual where to_char(t1.creation_date,'YYYY-MM-DD') = '2019-10-01' and t1.contract_status in ('PENDING', 'INCEPT', 'TERMINATE'))) <= to_date(#{leaseStartDateTo},'yyyy-MM-dd')
order by t1.contract_id desc

SELECT t.* from( SELECT cc.PROJECT_ID, cc.contract_id, cc.CONTRACT_NUMBER, (SELECT v.description value_name FROM hls_document_type v WHERE V.enabled_flag = 'Y' AND v.document_type = cc.document_type AND v.DOCUMENT_CATEGORY='CON_CONTRACT') document_type_n, (select m.bp_name from hls_bp_master m where m.bp_id = cc.manufacturer_id) manufacturer_id_n, ( SELECT hbv.bp_name FROM hls_bp_master hbv WHERE hbv.bp_id = cc.tenant_id ) tenant_id_n, cc.lease_item_type, (SELECT sc.meaning FROM sys_code_value_b_v sc WHERE sc.code = 'PRODUCT.LEASE_ITEM_TYPE' AND sc.CODE_VALUE=cc.LEASE_ITEM_TYPE ) lease_item_type_n, cc.division, (SELECT d.description FROM hls_division d WHERE d.division = cc.division ) division_n, (SELECT fe.NAME FROM FND_EMPLOYEE fe WHERE fe.EMPLOYEE_ID = cc.EMPLOYEE_ID ) employee_id_n, ( SELECT u.unit_name FROM fnd_org_unit u WHERE u.unit_id = cc.unit_id ) unit_id_n, ( SELECT h.actual_pay_date FROM csh_payment_req_hd h, csh_payment_req_ln l, con_contract_cashflow cf WHERE h.payment_req_id = l.payment_req_id AND l.source_doc_category = 'CON_CONTRACT' AND l.source_doc_id = cf.contract_id AND l.source_doc_line_id = cf.cashflow_id AND cf.contract_id = cc.contract_id ) actual_pay_date, cc.contract_status, (SELECT sc.meaning FROM sys_code_value_b_v sc WHERE sc.code = 'CON.CONTRACT_STATUS' AND sc.CODE_VALUE=cc.contract_status ) contract_status_n, (select lease_times from prj_quotation q where q.source_document_category = 'PRJ_PROJECT' and q.source_document_id=pp.PROJECT_ID) lease_times, (select finance_amount from prj_quotation q where source_document_category = 'PRJ_PROJECT' and q.source_document_id = pp.PROJECT_ID) finance_amount, (select sum(nvl(ccc.DUE_AMOUNT, 0)) from con_contract_cashflow ccc where ccc.contract_id =cc.contract_id and ccc.CF_ITEM = 1 and ccc.CF_STATUS = 'RELEASE') total_rental_amount, (select lease_end_date from prj_quotation q where source_document_category = 'PRJ_PROJECT' and q.source_document_id = pp.PROJECT_ID) lease_end_date, (SELECT SUM(ccc.due_amount-nvl(ccc.received_amount,0)) FROM CON_CONTRACT_CASHFLOW ccc WHERE ccc.contract_id=cc.contract_id and ccc.CF_ITEM=1 and ccc.CF_STATUS = 'RELEASE') remain_rental_amount, (SELECT SUM(ccc.principal-nvl(ccc.received_principal,0)) FROM CON_CONTRACT_CASHFLOW ccc WHERE ccc.contract_id=cc.contract_id and ccc.CF_ITEM=1 and ccc.CF_STATUS = 'RELEASE') remain_principal, (CASE WHEN (SELECT count(1) FROM con_contract_cashflow cf WHERE cf.contract_id = cc.contract_id AND cf.cf_item = 1 AND trunc( cf.due_date ) < trunc( SYSDATE ) AND cf.due_amount - nvl( cf.received_amount, 0 ) > 0 and cf.CF_STATUS = 'RELEASE' ) > 0 THEN 'Y' ELSE 'N' END) current_overdue_status, (CASE WHEN (SELECT count(1) FROM con_contract_cashflow cf WHERE cf.contract_id = cc.contract_id AND cf.cf_item = 1 AND trunc( cf.due_date ) < trunc( SYSDATE ) AND cf.due_amount - nvl( cf.received_amount, 0 ) > 0 and cf.CF_STATUS = 'RELEASE' ) > 0 THEN '是' ELSE '否' END) current_overdue_status_n, (CASE WHEN (SELECT count(1) FROM con_contract_cashflow cf WHERE cf.contract_id = cc.contract_id AND cf.cf_item = 1 AND nvl(cf.overdue_status,'N') = 'Y' and cf.CF_STATUS = 'RELEASE') > 0 THEN '是' ELSE '否' END)history_overdue_status, (SELECT MAX(cf.overdue_max_days) FROM con_contract_cashflow cf WHERE cf.contract_id = cc.contract_id AND cf.cf_item = 1) overdue_max_days, (SELECT sum(DUE_AMOUNT) FROM CON_CONTRACT_CASHFLOW WHERE cf_item=9 AND CONTRACT_ID=cc.contract_id and CF_STATUS = 'RELEASE')penalty, (CASE (SELECT CF_ITEM FROM CON_CONTRACT_CASHFLOW WHERE CONTRACT_ID = cc.CONTRACT_ID AND CF_STATUS not in ('BLOCK','CANCEL') AND CF_ITEM in (1,11,13) ORDER BY TIMES DESC FETCH FIRST 1 ROWS ONLY) WHEN 1 THEN 'NORMAL' WHEN 11 THEN 'ET' WHEN 13 THEN 'REPO' END ) terminate_type, (CASE (SELECT CF_ITEM FROM CON_CONTRACT_CASHFLOW WHERE CONTRACT_ID = cc.CONTRACT_ID AND CF_STATUS not in ('BLOCK','CANCEL') AND CF_ITEM in (1,11,13) ORDER BY TIMES DESC FETCH FIRST 1 ROWS ONLY) WHEN 1 THEN '正常结清' WHEN 11 THEN '提前结清' WHEN 13 THEN '回购' END ) terminate_type_n FROM con_contract cc LEFT JOIN prj_project pp ON cc.project_id = pp.project_id ) t
1=1 and t.contract_status in ('INCEPT','TERMINATE')
and t.contract_number like concat(concat('%',#{contractNumber}),'%')
and t.contract_status = #{contractStatus}
and t.current_overdue_status = #{currentOverdueStatus}
and t.terminate_type = #{terminateType}
order by t.contract_id desc

select  PLEDGE_PERSON,PLEDGE_LOCATION,PLEDGE_INSTITUTION,PLEDGE_DATE,PLEDGE_DESCRIPTION
from con_contract
where contract_id = #{contractId}
